import { SoundManager } from '../audio';
import { Difficulty, GameMode, ShapeType, UltimateType } from '../types';
import { DIFFICULTY_CONFIG } from '../constants';

interface GameOverScreenProps {
  score: number;
  wave: number;
  coinsEarned: number;
  onRestart: () => void;
  onOpenShop: () => void;
  onOpenUpgrades: () => void;
  onMainMenu: () => void;
  onOpenLeaderboard: () => void;
  gameMode?: GameMode;
}

export const GameOverScreen: React.FC<GameOverScreenProps> = ({ score, wave, coinsEarned, onRestart, onOpenShop, onOpenUpgrades, onMainMenu, onOpenLeaderboard, gameMode }) => {
  const handleRestart = () => {
    SoundManager.playClick();
    onRestart();
  };

  const handleShop = () => {
    SoundManager.playClick();
    onOpenShop();
  };

  const handleMainMenu = () => {
      SoundManager.playClick();
      onMainMenu();
  };

  return (
    <div 
        className="absolute inset-0 flex items-center justify-center bg-slate-950/80 backdrop-blur-sm z-50 animate-in fade-in duration-300 p-4"
        style={{ 
            paddingTop: 'var(--safe-top)', 
            paddingBottom: 'var(--safe-bottom)',
            paddingLeft: 'var(--safe-left)',
            paddingRight: 'var(--safe-right)'
        }}
    >
      <div className="bg-slate-900 p-6 md:p-10 rounded-3xl border border-red-900/50 shadow-2xl text-center max-w-md w-full max-h-full overflow-y-auto no-scrollbar relative">
        <div className="mb-4 inline-block p-3 bg-red-500/10 rounded-full border border-red-500/20">
            <Skull className="text-red-500 w-8 h-8 md:w-12 md:h-12" />
        </div>

        <h1 className="text-2xl md:text-5xl font-black text-white mb-1 tracking-tight uppercase italic">
            {gameMode === GameMode.TOWER ? "Ascension Halted" : "Mission Failed"}
        </h1>
        <p className="text-red-400/80 font-bold text-[10px] md:text-xs uppercase tracking-widest mb-4">System Critical</p>

        <div className="grid grid-cols-2 gap-3 mb-6">
            <div className="bg-slate-800/50 p-3 rounded-xl border border-slate-700">
                <div className="text-slate-400 text-[10px] uppercase font-bold mb-0.5">Score</div>
                <div className="text-xl md:text-3xl font-black text-cyan-400">
                    {score.toLocaleString()}
                </div>
            </div>
            <div className="bg-slate-800/50 p-3 rounded-xl border border-slate-700">
                <div className="text-slate-400 text-[10px] uppercase font-bold mb-0.5">
                    {gameMode === GameMode.TOWER ? "Floor" : "Wave"}
                </div>
                <div className="text-xl md:text-3xl font-black text-white flex items-center justify-center gap-2">
                    {wave}
                </div>
            </div>
             <div className="bg-slate-800/50 p-3 rounded-xl border border-slate-700 col-span-2 flex flex-col items-center">
                <div className="text-slate-400 text-[10px] uppercase font-bold mb-0.5">Coins Earned</div>
                <div className="text-2xl md:text-4xl font-black text-yellow-400 flex items-center justify-center gap-2">
                    <Coins size={24} />
                    +{coinsEarned}
                </div>
            </div>
        </div>

        <div className="space-y-2">
            <div className="flex gap-2">
                <button
                onClick={handleRestart}
                className="flex-1 py-3 md:py-4 bg-white text-slate-900 font-black rounded-xl text-lg md:text-xl hover:bg-slate-200 transition-colors active:scale-95 shadow-lg flex items-center justify-center gap-2"
                >
                <RotateCcw size={20} />
                RETRY
                </button>
            </div>

            <div className="grid grid-cols-1 gap-2">
                <button
                onClick={handleShop}
                className="py-2 md:py-3 bg-slate-800 text-slate-300 font-bold rounded-xl text-xs md:text-base hover:bg-slate-700 hover:text-white transition-colors active:scale-95 border border-slate-700"
                >
                ARMORY
