interface StartScreenProps {
  onStart: (startFloor?: number) => void;
  onOpenShop: () => void;
  onOpenSettings: () => void;
  onOpenManual: () => void;
  onPlayTutorial: () => void;
  onDifficultyChange: (d: Difficulty) => void;
  gameMode: GameMode;
  difficulty: Difficulty;
  towerFloors: Record<Difficulty, number>;
}

export const StartScreen: React.FC<StartScreenProps> = ({ 
    onStart, 
    onOpenShop, 
    onOpenSettings, 
    onOpenManual, 
    onPlayTutorial, 
    onDifficultyChange,
    gameMode,
    difficulty,
    towerFloors
}) => {
    const [showResumeModal, setShowResumeModal] = useState(false);

    const handleStartClick = () => {
        SoundManager.playClick();
        if (gameMode === GameMode.TOWER) {
            const savedFloor = towerFloors[difficulty] || 1;
            if (savedFloor > 1) {
                setShowResumeModal(true);
                return;
            }
        }
        onStart();
    };

    const handleResume = () => {
        SoundManager.playClick();
        const savedFloor = towerFloors[difficulty] || 1;
        onStart(savedFloor);
        setShowResumeModal(false);
    };

    const handleNewGame = () => {
        SoundManager.playClick();
        onStart(1);
        setShowResumeModal(false);
    };

    const currentTowerFloor = towerFloors[difficulty] || 1;

    return (
        <div 
            className="absolute inset-0 flex flex-col items-center justify-center bg-slate-950 z-50 overflow-hidden"
            style={{ 
                paddingTop: 'var(--safe-top)', 
                paddingBottom: 'var(--safe-bottom)',
                paddingLeft: 'var(--safe-left)',
                paddingRight: 'var(--safe-right)'
            }}
        >
             {/* Dynamic Background Elements */}
             <div className="absolute inset-0 pointer-events-none opacity-20 overflow-hidden">
                <div className="absolute top-1/4 -left-20 w-96 h-96 bg-cyan-500/20 rounded-full blur-[120px] animate-pulse" />
                <div className="absolute bottom-1/4 -right-20 w-96 h-96 bg-purple-500/20 rounded-full blur-[120px] animate-pulse" />
             </div>

             {/* Game Name */}
             <div className="shrink-0 mb-6 md:mb-10 text-center animate-in zoom-in duration-700 px-4 relative">
                  <h1 className="text-6xl md:text-8xl lg:text-9xl font-black text-transparent bg-clip-text bg-gradient-to-br from-cyan-400 via-blue-500 to-purple-600 tracking-tighter drop-shadow-[0_0_30px_rgba(6,182,212,0.3)] italic uppercase leading-none select-none">
                      Trishift
                  </h1>
                  <div className="text-white text-[10px] md:text-sm font-black tracking-[0.4em] mt-3 uppercase opacity-60 italic flex items-center justify-center gap-3">
                      <div className="h-px w-8 bg-gradient-to-r from-transparent to-white/40" />
                      Victory is your crown
                      <div className="h-px w-8 bg-gradient-to-l from-transparent to-white/40" />
                  </div>
             </div>

             {/* Navigation Stack */}
             <div className="w-full max-w-sm md:max-w-md px-6 space-y-4 relative z-10">
                  {/* Difficulty Selector */}
                  <div className="bg-slate-900/60 backdrop-blur-md p-1.5 rounded-2xl border border-slate-700/50 shadow-xl">
                      <div className="flex gap-1">
                          {(Object.keys(Difficulty) as Difficulty[]).map((d) => {
                              const config = DIFFICULTY_CONFIG[d];
                              const isActive = difficulty === d;
                              return (
                                  <button
                                      key={d}
                                      onClick={() => { SoundManager.playClick(); onDifficultyChange(d); }}
                                      className={`flex-1 py-3 rounded-xl flex flex-col items-center justify-center transition-all duration-300 ${
                                          isActive 
                                          ? `bg-slate-800 border-2 shadow-[inset_0_0_15px_rgba(255,255,255,0.05)]` 
                                          : 'opacity-40 hover:opacity-60 grayscale-[0.5]'
                                      }`}
                                      style={{ borderColor: isActive ? config.color : 'transparent' }}
                                  >
                                      <span className="text-[10px] font-black uppercase tracking-tighter" style={{ color: config.color }}>{config.label}</span>
                                      {isActive && <div className="text-[7px] text-slate-400 font-bold uppercase mt-0.5 leading-none px-1 text-center">{config.description.split('.')[0]}</div>}
                                  </button>
                              );
                          })}
                      </div>
                  </div>

                  {/* Primary Action: Engage Mission */}
                  <button 
                      onClick={handleStartClick} 
                      className="group relative w-full py-5 md:py-7 bg-white text-slate-900 font-black text-2xl md:text-3xl rounded-2xl transition-all active:scale-95 shadow-[0_20px_50px_rgba(255,255,255,0.1)] flex flex-col items-center justify-center border-b-4 border-slate-300 overflow-hidden"
                  >
                       <div className="absolute inset-0 bg-[linear-gradient(to_right,transparent_25%,rgba(6,182,212,0.2)_50%,transparent_75%)] bg-[length:200%_100%] animate-shimmer pointer-events-none" />
                       <div className="flex items-center gap-4 z-10 relative">
                           <Play size={28} className="fill-slate-900 group-hover:scale-110 transition-transform" />
                           <span className="tracking-tight italic uppercase">Engage Mission</span>
                       </div>
                  </button>

                  {/* Secondary Grid */}
                  <div className="grid grid-cols-2 gap-3">
                      <button 
                          onClick={() => { SoundManager.playClick(); onOpenShop(); }} 
                          className="group py-4 bg-slate-900/60 backdrop-blur-md text-slate-300 font-bold rounded-xl border border-slate-700/50 hover:border-blue-500/50 hover:bg-slate-800 transition-all active:scale-95 flex flex-col items-center justify-center gap-2 shadow-lg"
                      >
                          <ShoppingCart size={20} className="text-blue-400 group-hover:scale-110 transition-transform" />
                          <span className="text-[10px] md:text-xs uppercase tracking-widest font-black">Armory</span>
                      </button>

                      <button 
                          onClick={() => { SoundManager.playClick(); onPlayTutorial(); }} 
                          className="group py-4 bg-slate-900/60 backdrop-blur-md text-slate-300 font-bold rounded-xl border border-slate-700/50 hover:border-cyan-500/50 hover:bg-slate-800 transition-all active:scale-95 flex flex-col items-center justify-center gap-2 shadow-lg"
                      >
                          <GraduationCap size={20} className="text-cyan-400 group-hover:scale-110 transition-transform" />
                          <span className="text-[10px] md:text-xs uppercase tracking-widest font-black">Tutorial</span>
                      </button>

                      <button 
                          onClick={() => { SoundManager.playClick(); onOpenSettings(); }} 
                          className="group py-4 bg-slate-900/60 backdrop-blur-md text-slate-300 font-bold rounded-xl border border-slate-700/50 hover:border-slate-500 hover:bg-slate-800 transition-all active:scale-95 flex flex-col items-center justify-center gap-2 shadow-lg"
                      >
                          <Settings size={20} className="text-slate-400 group-hover:rotate-45 transition-transform" />
                          <span className="text-[10px] md:text-xs uppercase tracking-widest font-black">Config</span>
                      </button>

                      <button 
                          onClick={() => { SoundManager.playClick(); onOpenManual(); }} 
                          className="group py-4 bg-slate-900/60 backdrop-blur-md text-slate-300 font-bold rounded-xl border border-slate-700/50 hover:border-amber-500/50 hover:bg-slate-800 transition-all active:scale-95 flex flex-col items-center justify-center gap-2 shadow-lg"
                      >
                          <BookOpen size={20} className="text-amber-400 group-hover:scale-110 transition-transform" />
                          <span className="text-[10px] md:text-xs uppercase tracking-widest font-black">Tactical</span>
                      </button>
                  </div>
             </div>

             {/* Resume Modal */}
             {showResumeModal && (
                <div className="absolute inset-0 z-[60] flex items-center justify-center bg-slate-950/90 backdrop-blur-md p-4 animate-in fade-in duration-300">
                    <div className="bg-slate-900 border border-cyan-500/50 p-8 rounded-3xl shadow-2xl max-w-sm w-full animate-in zoom-in-95 flex flex-col gap-5 text-center relative overflow-hidden">
                        <div className="absolute top-0 left-0 w-full h-1 bg-cyan-500 opacity-50" />
                        <h2 className="text-2xl font-black text-white uppercase italic">Resume Ascension?</h2>
                        <p className="text-slate-400 text-sm">Synchronized Floor <span className="text-cyan-400 font-bold font-mono">#{currentTowerFloor}</span> detected.</p>
                        <div className="space-y-3 mt-2">
                            <button onClick={handleResume} className="w-full py-4 bg-cyan-600 text-white font-black rounded-xl text-lg hover:bg-cyan-500 transition-all active:scale-95 shadow-xl flex items-center justify-center gap-3 italic"><ArrowUpCircle size={24} /> CONTINUE</button>
                            <button onClick={handleNewGame} className="w-full py-3 bg-slate-800 text-slate-400 font-bold rounded-xl text-sm border border-slate-700 hover:text-white transition-colors">NEW SEQUENCE</button>
                            <button onClick={() => setShowResumeModal(false)} className="text-slate-500 text-[10px] uppercase font-black tracking-widest hover:text-rose-500 transition-colors pt-2">Terminate Request</button>
                        </div>
                    </div>
                </div>
             )}

             {/* Version Info Footer */}
             <div className="absolute bottom-6 text-[8px] md:text-[10px] font-black text-slate-700 uppercase tracking-[0.5em] select-none">
                 Operational Environment v1.0.7-S
             </div>
        </div>
    );
};

