export const EscapeTutorialOverlay: React.FC<{ onDismiss: () => void }> = ({ onDismiss }) => {
    const [step, setStep] = useState(0);
    const steps = [
        { title: "Escape Protocols", desc: "Survival is the only objective. In this mode, combat is secondary—evasion is absolute.", icon: <Wind className="text-cyan-400 w-12 h-12" />, color: "cyan" },
        { title: "Phase Dash", desc: "Use Dash to instantly relocate. Invaluable for passing through tight clusters of enemies.", controls: { pc: "Shift", mobile: "Wind Icon" }, icon: <Wind className="text-cyan-400 w-12 h-12" />, color: "cyan" },
        { title: "Pulse Shield", desc: "Activate a temporary kinetic barrier. It grants total invulnerability for a brief period.", controls: { pc: "Q", mobile: "Shield Icon" }, icon: <Shield className="text-blue-400 w-12 h-12" />, color: "blue" },
        { title: "Temporal Dilation", desc: "Hold to slow down time. Use your Energy Meter wisely to navigate lethal patterns.", controls: { pc: "E (Hold)", mobile: "Hourglass Icon" }, icon: <Hourglass className="text-purple-400 w-12 h-12" />, color: "purple" }
    ];
    const current = steps[step];
    return (
        <div className="absolute inset-0 z-[100] flex items-center justify-center bg-slate-950/90 backdrop-blur-md p-4">
            <div className={`bg-slate-900 border border-${current.color}-500/30 p-8 rounded-[2rem] shadow-2xl max-w-lg w-full flex flex-col items-center text-center gap-5 relative animate-in zoom-in-95`}>
                 <div className={`absolute top-0 inset-x-0 h-1 bg-${current.color}-500 opacity-50`} />
                 <div className={`bg-${current.color}-500/10 p-4 rounded-full border border-${current.color}-500/20 mb-1 animate-pulse`}>{current.icon}</div>
                 <h2 className={`text-2xl md:text-3xl font-black text-white uppercase italic tracking-tight`}>{current.title}</h2>
                 <p className="text-slate-400 text-xs md:text-sm leading-relaxed">{current.desc}</p>
                 {current.controls && (
                    <div className="grid grid-cols-2 gap-3 w-full">
                        <div className="bg-slate-950/50 p-2 rounded-lg border border-slate-800 flex flex-col"><span className="text-[8px] text-slate-500 font-black uppercase">PC</span><span className="text-white font-mono font-bold text-sm">{current.controls.pc}</span></div>
                        <div className="bg-slate-950/50 p-2 rounded-lg border border-slate-800 flex flex-col"><span className="text-[8px] text-slate-500 font-black uppercase">MOBILE</span><span className="text-white font-bold text-[10px] uppercase">{current.controls.mobile}</span></div>
                    </div>
                 )}
                 <div className="flex gap-2 w-full mt-2">
                    {step > 0 && <button onClick={() => { SoundManager.playClick(); setStep(s => s - 1); }} className="flex-1 py-3 rounded-xl bg-slate-800 text-slate-400 font-black uppercase text-xs">Back</button>}
                    <button onClick={() => { SoundManager.playClick(); if (step < steps.length - 1) setStep(s => s + 1); else onDismiss(); }} className={`flex-[2] py-3 rounded-xl bg-${current.color}-600 text-white font-black uppercase text-xs shadow-lg flex items-center justify-center gap-2`}>{step < steps.length - 1 ? "Next" : "Engage"} <ChevronRight size={16} /></button>
                 </div>
                 <div className="flex gap-1 mt-1">{steps.map((_, i) => <div key={i} className={`h-1 rounded-full transition-all duration-300 ${i === step ? `w-6 bg-${current.color}-500` : 'w-1 bg-slate-800'}`} />)}</div>
            </div>
        </div>
    );
};

