        const squareHP = (upgrades[ShapeType.SQUARE]?.STAT_4 || 0) * UPGRADE_TREE[ShapeType.SQUARE].STAT_4.increment;
        const triangleHP = (upgrades[ShapeType.TRIANGLE]?.STAT_4 || 0) * UPGRADE_TREE[ShapeType.TRIANGLE].STAT_4.increment;
