      spawnParticles(playerRef.current.position, 40, energyColor, 300, 0.6, 3);
      if (shape === ShapeType.CIRCLE) SoundManager.playUltDash();
      if (shape === ShapeType.SQUARE) SoundManager.playUltShield();
      if (shape === ShapeType.TRIANGLE) SoundManager.playUltBlade();
      if (selectedUlt === UltimateType.PHANTOM_STRIKES) {
          const targets = enemiesRef.current.map(e => ({ e, dist: getDistance(playerRef.current.position, e.position) })).sort((a, b) => a.dist - b.dist).slice(10);
          targets.forEach(({ e }) => {
               e.health -= 200; e.hitFlash = 0.2; spawnParticles(e.position, 8, energyColor, 150, 0.4, 3);
               projectilesRef.current.push({ id: Math.random().toString(), position: { ...playerRef.current.position }, velocity: { x: e.position.x - playerRef.current.position.x, y: e.position.y - playerRef.current.position.y }, radius: 0, color: energyColor, rotation: 0, damage: 0, life: 0.2, maxLife: 0.2, type: 'SNIPER_SHOT' });
          });
          screenShakeRef.current = 5;
      }
      if (selectedUlt === UltimateType.GRAVITY_SLAM) {
          projectilesRef.current.push({ id: Math.random().toString(), position: { ...playerRef.current.position }, velocity: { x: 0, y: 0 }, radius: 150, color: energyColor, rotation: 0, damage: 5, life: 4.0, maxLife: 4.0, type: 'SHOCKWAVE' });
          screenShakeRef.current = 10;
      }
      if (selectedUlt === UltimateType.RAPTOR_FRENZY) {
           const targets = enemiesRef.current.map(e => ({ id: e.id, dist: getDistance(playerRef.current.position, e.position) })).sort((a, b) => a.dist - b.dist).slice(0, 12);
           playerRef.current.raptorTargets = targets.map(t => t.id);
           playerRef.current.raptorIndex = 0;
           if (targets.length === 0) { playerRef.current.ultActiveTimer = 0; playerRef.current.ultimateCharge = 100; propsRef.current.onUltChargeChange(100); }
      }
      if (selectedUlt === UltimateType.TIME_SKIP) { playerRef.current.timeSkipCounter = 0; playerRef.current.timeSkipTimer = 0; }
  }, [skin, getSkinThemeColor]); 

  const changeShape = useCallback((newShape: ShapeType) => {
      if (newShape === playerRef.current.shape) return;

      if (waveRef.current === 0) {
          if (newShape === ShapeType.TRIANGLE) wave0FlagsRef.current.add('shifted_triangle');
          if (newShape === ShapeType.SQUARE) wave0FlagsRef.current.add('shifted_square');

          if (wave0FlagsRef.current.has('waiting_for_square') && newShape === ShapeType.SQUARE) {
              spawnFloatingText(playerRef.current.position, "GOOD SHIFT", "#6366f1", 1.5);
