              wave0FlagsRef.current.add('square_done');
              if (propsRef.current.onTutorialHighlight) propsRef.current.onTutorialHighlight(null);
          }
          if (wave0FlagsRef.current.has('waiting_for_triangle') && newShape === ShapeType.TRIANGLE) {
              spawnFloatingText(playerRef.current.position, "GOOD SHIFT", "#f59e0b", 1.5);
