          if (wave0TimerRef.current >= 10.0 && wave0TimerRef.current < 20.0 && !wave0FlagsRef.current.has('perfect_shift_done')) {
              if (wave0FlagsRef.current.has('shifted_triangle') && wave0FlagsRef.current.has('shifted_square')) {
                  wave0FlagsRef.current.add('perfect_shift_done');
                  spawnFloatingText(playerRef.current.position, "PERFECT SHIFT!", "#22d3ee", 1.5);
                  screenShakeRef.current = 3;
                  enemiesRef.current.forEach(e => {
                      const angle = Math.atan2(e.position.y - playerRef.current.position.y, e.position.x - playerRef.current.position.x);
                      e.position.x += Math.cos(angle) * 150; e.position.y += Math.sin(angle) * 150;
