    const handleKeyDown = (e: KeyboardEvent) => {
      SoundManager.init();
      if (propsRef.current.isPaused) return;
      keysPressed.current.add(e.key.toLowerCase());
      let newShape: ShapeType | null = null;
      if (KEYS.SHAPE_CIRCLE.includes(e.key)) newShape = ShapeType.CIRCLE;
      if (KEYS.SHAPE_SQUARE.includes(e.key)) newShape = ShapeType.SQUARE;
      if (KEYS.SHAPE_TRIANGLE.includes(e.key)) newShape = ShapeType.TRIANGLE;
      if (newShape) changeShape(newShape);
