          ctx.save(); ctx.translate(player.position.x, player.position.y - 70 + Math.sin(timeRef.current * 4) * 8); ctx.shadowColor = '#d946ef'; ctx.shadowBlur = 15 + Math.sin(timeRef.current * 10) * 10; ctx.fillStyle = 'rgba(15, 23, 42, 0.9)'; ctx.strokeStyle = '#d946ef'; ctx.lineWidth = 2; const w = 100, h = 36, r = 6; ctx.beginPath(); ctx.moveTo(-w/2+r, -h/2); ctx.lineTo(w/2-r, -h/2); ctx.quadraticCurveTo(w/2, -h/2, w/2, -h/2+r); ctx.lineTo(w/2, h/2-r); ctx.quadraticCurveTo(w/2, h/2, w/2-r, h/2); ctx.lineTo(-w/2+r, h/2); ctx.quadraticCurveTo(-w/2, h/2, -w/2, h/2-r); ctx.lineTo(-w/2, -h/2+r); ctx.quadraticCurveTo(-w/2, -h/2, -w/2+r, -h/2); ctx.closePath(); ctx.fill(); ctx.stroke(); ctx.shadowBlur = 0; ctx.fillStyle = '#fff'; ctx.font = "bold 16px sans-serif"; ctx.textAlign = "center"; ctx.textBaseline = "middle"; ctx.fillText("SPACE", 0, 1); ctx.font = "bold 12px sans-serif"; ctx.fillStyle = "#d946ef"; ctx.shadowColor = 'black'; ctx.shadowBlur = 4; ctx.fillText("ULTIMATE READY", 0, -30); ctx.restore();
