};

export default GameCanvas;

import React, { useState, useEffect, useCallback } from 'react';
import GameCanvas from './components/GameCanvas';
import HUD from './components/HUD';
import { GameOverScreen, StartScreen, TutorialSuccessScreen, EscapeTutorialOverlay, TowerTutorialOverlay } from './components/Screens';
import Shop from './components/Shop';
import UpgradeMenu from './components/UpgradeMenu';
import SettingsMenu from './components/SettingsMenu';
import Manual from './components/Manual';
import MiniShop from './components/MiniShop';
import Leaderboard from './components/Leaderboard';
import { ShapeType, ItemType, EquippedLoadout, JoystickOutput, UpgradeState, GameSettings, Difficulty, GameMode, ThemeType, SkinType, UltimateType, UpgradeStat, Mission } from './types';
import { PLAYER_MAX_HEALTH, MISSIONS } from './constants';
import { Persistence } from './storage';
import { SoundManager } from './audio';
import { MobileControls } from './components/MobileControls';

const App: React.FC = () => {
  const [view, setView] = useState<'GAME' | 'SHOP' | 'UPGRADES' | 'SETTINGS' | 'MANUAL' | 'LEADERBOARD'>('GAME');
  const [previousView, setPreviousView] = useState<'GAME' | 'SHOP' | 'UPGRADES'>('GAME'); 

  const [gameStarted, setGameStarted] = useState(false);

  const [health, setHealth] = useState(PLAYER_MAX_HEALTH);
  const [maxHealth, setMaxHealth] = useState(PLAYER_MAX_HEALTH);
  const [score, setScore] = useState(0);
  const [wave, setWave] = useState(0);
  const [currentShape, setCurrentShape] = useState<ShapeType>(ShapeType.CIRCLE);
  const [requestedShape, setRequestedShape] = useState<ShapeType | null>(null);
  const [activeBuffs, setActiveBuffs] = useState<{ type: ItemType; time: number }[]>([]);
  const [ultCharge, setUltCharge] = useState(0);
  const [bossHealth, setBossHealth] = useState<{current: number; max: number; name: string | null}>({current: 0, max: 100, name: null});
  const [isGameOver, setIsGameOver] = useState(false);

  const [isPaused, setIsPaused] = useState(false);
  const [isSlowMo, setIsSlowMo] = useState(false);
  const [ultTrigger, setUltTrigger] = useState(0);
  const [restartTrigger, setRestartTrigger] = useState(0);
  const [tutorialMode, setTutorialMode] = useState(false);
  const [isTutorialRun, setIsTutorialRun] = useState(false);
  const [tutorialCompleted, setTutorialCompleted] = useState(false);
  const [tutorialSuccess, setTutorialSuccess] = useState(false);
  const [tutorialHighlight, setTutorialHighlight] = useState<ShapeType | null>(null); 
  const [tutorialUltHighlight, setTutorialUltHighlight] = useState(false); 

  const [showEscapeTutorial, setShowEscapeTutorial] = useState(false);
  const [hasSeenEscapeTutorial, setHasSeenEscapeTutorial] = useState(false);
  const [showTowerTutorial, setShowTowerTutorial] = useState(false);
  const [hasSeenTowerTutorial, setHasSeenTowerTutorial] = useState(false);

  const [difficulty, setDifficulty] = useState<Difficulty>(Difficulty.EASY);
  const [gameMode, setGameMode] = useState<GameMode>(GameMode.SURVIVAL);

  const [playerHasMoved, setPlayerHasMoved] = useState(false);
  const [playerHasAimed, setPlayerHasAimed] = useState(false);
  const [showAimHintTrigger, setShowAimHintTrigger] = useState(false);

  const [escapeTimer, setEscapeTimer] = useState(0);
  const [showMiniShop, setShowMiniShop] = useState(false);

  const [themeAnomaly, setThemeAnomaly] = useState(false);
  const [hasSeenThemeAnomaly, setHasSeenThemeAnomaly] = useState(false);
  const [graphicsSuggestion, setGraphicsSuggestion] = useState(false);
  const [hasSeenGraphicsSuggestion, setHasSeenGraphicsSuggestion] = useState(false);
  const [shopInitialTab, setShopInitialTab] = useState<'SKINS' | 'THEMES' | 'ULTIMATES'>('SKINS');

  const [moveInput, setMoveInput] = useState<JoystickOutput>({ x: 0, y: 0, active: false });
  const [aimInput, setAimInput] = useState<JoystickOutput>({ x: 0, y: 0, active: false });

  const [triggerDash, setTriggerDash] = useState(0);
  const [triggerShield, setTriggerShield] = useState(0);
  const [isSlowMoHeld, setIsSlowMoHeld] = useState(false);
  const [escapeState, setEscapeState] = useState<{ dashCooldown: number, shieldCooldown: number, slowMoCharge: number } | undefined>(undefined);

  const [coins, setCoins] = useState(0);
  const [unlockedItems, setUnlockedItems] = useState<string[]>([]);
  const [equipped, setEquipped] = useState<EquippedLoadout | undefined>(undefined);
  const [upgrades, setUpgrades] = useState<UpgradeState | undefined>(undefined);
  const [settings, setSettings] = useState<GameSettings>({ 
    musicVolume: 0.5, 
    sfxVolume: 0.5, 
    leftHanded: false, 
    graphics: 'MEDIUM', 
    ultPosition: 'CORNER', 
    autoFirePC: true,
    minimalAndroidHUD: false,
    hideHudDetails: false,
    moveSensitivity: 1.0,
    aimSensitivity: 1.0
  });
  const [towerFloors, setTowerFloors] = useState<Record<Difficulty, number>>({ [Difficulty.EASY]: 1, [Difficulty.NORMAL]: 1, [Difficulty.HARD]: 1 });
  const [highestSurvivalWave, setHighestSurvivalWave] = useState(0);
  const [missionIndex, setMissionIndex] = useState(0);

  const [isTouchDevice, setIsTouchDevice] = useState(false);

  useEffect(() => {
    setIsTouchDevice('ontouchstart' in window || navigator.maxTouchPoints > 0);

    const progress = Persistence.loadProgress();
    setCoins(progress.coins);
    setUnlockedItems(progress.unlockedItems);
    setEquipped(progress.equipped);
    setUpgrades(progress.upgrades);
    setSettings(progress.settings);
    setTutorialCompleted(progress.tutorialCompleted);
    setHasSeenEscapeTutorial(progress.hasSeenEscapeTutorial || false);
    setHasSeenTowerTutorial(progress.hasSeenTowerTutorial || false);
    setTowerFloors(progress.towerFloor);
    setHighestSurvivalWave(progress.highestSurvivalWave);
    setMissionIndex(progress.missionIndex);
    setHasSeenThemeAnomaly(progress.hasSeenThemeAnomaly || false);
    setHasSeenGraphicsSuggestion(progress.hasSeenGraphicsSuggestion || false);

    SoundManager.updateVolumes(progress.settings.musicVolume, progress.settings.sfxVolume);

    if (progress.tutorialCompleted && !(progress.hasSeenThemeAnomaly)) {
        if (Math.random() < 0.2) { 
             setThemeAnomaly(true);
        }
    }
  }, []);

  useEffect(() => {
    if (!hasSeenGraphicsSuggestion && !graphicsSuggestion && gameStarted && gameMode === GameMode.SURVIVAL && wave >= 2 && settings.graphics === 'MEDIUM') {
        const dpr = window.devicePixelRatio || 1;
        const isDesktop = !('ontouchstart' in window);
        if (dpr >= 2 || isDesktop) {
            setGraphicsSuggestion(true);
        }
    }
  }, [wave, hasSeenGraphicsSuggestion, graphicsSuggestion, gameStarted, gameMode, settings.graphics]);

  useEffect(() => {
      let timer: number;
      if (gameStarted && wave === 0 && !playerHasAimed) {
          const delay = playerHasMoved ? 1000 : 5000;
          timer = window.setTimeout(() => {
              setShowAimHintTrigger(true);
          }, delay);
      }
      return () => clearTimeout(timer);
  }, [gameStarted, wave, playerHasMoved, playerHasAimed]);

  const handleStart = (startFloor: number = 1) => {
      let waveToStart = startFloor;

      if (!tutorialCompleted && gameMode === GameMode.SURVIVAL && startFloor === 1) {
          waveToStart = 0;
      }

      let needsPause = false;
      if (gameMode === GameMode.ESCAPE && !hasSeenEscapeTutorial) {
          setShowEscapeTutorial(true);
          needsPause = true;
      }

      if (gameMode === GameMode.TOWER && !hasSeenTowerTutorial) {
          setShowTowerTutorial(true);
          needsPause = true;
      }

      setGameStarted(true);
      setIsGameOver(false);
      setIsPaused(needsPause);
      setWave(waveToStart); 
      setScore(0);
      setRestartTrigger(prev => prev + 1);
      setTutorialSuccess(false);
      setPlayerHasMoved(false);
      setPlayerHasAimed(false);
      setShowAimHintTrigger(false);
      setTutorialHighlight(null);
      setTutorialUltHighlight(false);

      SoundManager.startMusic();
  };

  const handleDismissEscapeTutorial = () => {
      setShowEscapeTutorial(false);
      setIsPaused(false);
      setHasSeenEscapeTutorial(true);
      Persistence.completeEscapeTutorial();
  };

  const handleDismissTowerTutorial = () => {
      setShowTowerTutorial(false);
      setIsPaused(false);
      setHasSeenTowerTutorial(true);
      Persistence.completeTowerTutorial();
  };

  const handleRestart = () => {
      const startWave = isTutorialRun ? 0 : (gameMode === GameMode.TOWER ? (towerFloors[difficulty] || 1) : 1);
      handleStart(startWave);
  };

  const handleGameOver = () => {
      setIsGameOver(true);
      if (gameMode === GameMode.SURVIVAL) {
          Persistence.saveSurvivalProgress(wave);
          Persistence.saveLocalScore(score, wave, GameMode.SURVIVAL);
      } else if (gameMode === GameMode.TOWER) {
          Persistence.saveTowerFloor(wave, difficulty);
          Persistence.saveLocalScore(score, wave, GameMode.TOWER);
      } else if (gameMode === GameMode.ESCAPE) {
          Persistence.saveLocalScore(score, wave, GameMode.ESCAPE);
      }
      const p = Persistence.loadProgress();
      setCoins(p.coins);
      setTowerFloors(p.towerFloor);
      setHighestSurvivalWave(p.highestSurvivalWave);
  };

  const handleGameWin = () => {
       setIsGameOver(true);
       Persistence.saveLocalScore(score, wave, gameMode);
       const p = Persistence.loadProgress();
       setCoins(p.coins);
       setTowerFloors(p.towerFloor);
       setHighestSurvivalWave(p.highestSurvivalWave);
  };

  useEffect(() => {
      if (isPaused) {
          SoundManager.pause();
      } else if (gameStarted && !isGameOver) {
          SoundManager.resume();
      }
  }, [isPaused, gameStarted, isGameOver]);

  const handlePause = useCallback(() => {
      setIsPaused(prev => {
          const next = !prev;
          if (next) {
              setMoveInput({ x: 0, y: 0, active: false });
              setAimInput({ x: 0, y: 0, active: false });
              setTriggerDash(0);
              setTriggerShield(0);
              setIsSlowMoHeld(false);
          }
          return next;
      });
  }, []);

  useEffect(() => {
      const handleBlur = () => {
          if (gameStarted && !isGameOver && !isPaused) {
              setIsPaused(true);
              setMoveInput({ x: 0, y: 0, active: false });
              setAimInput({ x: 0, y: 0, active: false });
          }
      };
      const handleVisibilityChange = () => { if (document.hidden) handleBlur(); };
      window.addEventListener('blur', handleBlur);
      document.addEventListener('visibilitychange', handleVisibilityChange);
      return () => {
          window.removeEventListener('blur', handleBlur);
          document.removeEventListener('visibilitychange', handleVisibilityChange);
      };
  }, [gameStarted, isGameOver, isPaused]);

  useEffect(() => {
    const handleGlobalKeyDown = (e: KeyboardEvent) => {
        if (!gameStarted || isGameOver) return;
        if (e.repeat) return;
        if (['w', 'a', 's', 'd', 'arrowup', 'arrowdown', 'arrowleft', 'arrowright'].includes(e.key.toLowerCase())) {
            setPlayerHasMoved(true);
        }
        // Removed Escape key listener use
        if (e.key.toLowerCase() === 'p') {
            if (view === 'GAME') {
                if (!showEscapeTutorial && !showTowerTutorial) handlePause();
            }
        }
    };
    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, [gameStarted, isGameOver, view, previousView, handlePause, showEscapeTutorial, showTowerTutorial]);

  const handleQuit = () => {
      if (gameMode === GameMode.SURVIVAL) {
          Persistence.saveSurvivalProgress(wave);
          Persistence.saveLocalScore(score, wave, GameMode.SURVIVAL);
      } else if (gameMode === GameMode.TOWER) {
           Persistence.saveTowerFloor(wave, difficulty);
           Persistence.saveLocalScore(score, wave, GameMode.TOWER);
      } else if (gameMode === GameMode.ESCAPE) {
           Persistence.saveLocalScore(score, wave, GameMode.ESCAPE);
      }
      const p = Persistence.loadProgress();
      setCoins(p.coins);
      setTowerFloors(p.towerFloor);
      setHighestSurvivalWave(p.highestSurvivalWave);
      setGameStarted(false);
      setIsGameOver(false);
      setIsPaused(false);
      setShowEscapeTutorial(false);
      setShowTowerTutorial(false);
      setTutorialHighlight(null);
      setTutorialUltHighlight(false);
      SoundManager.setMusicIntensity(0);
      SoundManager.stopMusic();
  };

  const handleBuy = (item: any) => {
      if (Persistence.unlockItem(item.id, item.cost)) {
           setCoins(prev => prev - item.cost);
           setUnlockedItems(prev => [...prev, item.id]);
           SoundManager.playPowerup();
           return true;
      }
      return false;
  };

  const handleEquip = (type: 'THEME' | 'SKIN' | 'SHAPE' | 'ULTIMATE', value: any, shape?: ShapeType) => {
      if (type === 'THEME') {
          Persistence.equipTheme(value as ThemeType);
          setEquipped(prev => prev ? { ...prev, theme: value } : undefined);
      } else if (type === 'SKIN') {
          Persistence.equipSkin(value as SkinType);
          setEquipped(prev => prev ? { ...prev, skin: value } : undefined);
      } else if (type === 'ULTIMATE' && shape) {
          Persistence.equipUltimate(shape, value as UltimateType);
          setEquipped(prev => prev ? { ...prev, ultimates: { ...prev.ultimates, [shape]: value } } : undefined);
      }
      SoundManager.playClick();
  };

  const handleUpgrade = (shape: ShapeType, stat: UpgradeStat) => {
      if (Persistence.purchaseUpgrade(shape, stat)) {
           const p = Persistence.loadProgress();
           setCoins(p.coins);
           setUpgrades(p.upgrades);
           SoundManager.playPowerup();
      }
  };

  const handleUpdateSettings = (newSettings: GameSettings) => {
      setSettings(newSettings);
      Persistence.saveSettings(newSettings);
      SoundManager.updateVolumes(newSettings.musicVolume, newSettings.sfxVolume);
  };

  const handleResetProgress = () => {
      Persistence.resetProgress();
      const p = Persistence.loadProgress();
      setCoins(p.coins);
      setUnlockedItems(p.unlockedItems);
      setEquipped(p.equipped);
      setUpgrades(p.upgrades);
      setSettings(p.settings);
      setTutorialCompleted(p.tutorialCompleted);
      setHasSeenEscapeTutorial(false);
      setHasSeenTowerTutorial(false);
      setTowerFloors(p.towerFloor);
      setHighestSurvivalWave(p.highestSurvivalWave);
      setMissionIndex(p.missionIndex);
      setHasSeenThemeAnomaly(false);
      setHasSeenGraphicsSuggestion(false);
      setGameStarted(false); 
      setIsGameOver(false);
      setIsPaused(false);
      setWave(0);
      setTutorialHighlight(null);
      setTutorialUltHighlight(false);
      SoundManager.stopMusic();
      setView('GAME');
  };

  const handleAddCoins = (amount: number) => {
      const newTotal = Persistence.addCoins(amount);
      setCoins(newTotal);
  };

  const handleToggleAutoFirePC = () => {
      const newSettings = { ...settings, autoFirePC: !settings.autoFirePC };
      handleUpdateSettings(newSettings);
      SoundManager.playClick();
  };

  const handleShapeRequestProcessed = useCallback(() => {
    setRequestedShape(null);
  }, []);

  const startTutorialRun = () => {
      setIsTutorialRun(true);
      setGameMode(GameMode.SURVIVAL);
      handleStart(0);
  };

  const handleTutorialComplete = () => {
      if (!tutorialCompleted) {
          Persistence.completeTutorial();
          setTutorialCompleted(true);
      }
  };

  const handleTutorialSuccess = () => {
      setIsGameOver(false);
      setGameStarted(false);
      setTutorialSuccess(true);
      handleTutorialComplete();
  };

  const handlePlayerAimed = useCallback(() => {
      setPlayerHasAimed(true);
  }, []);

  useEffect(() => {
     if (gameStarted && !isGameOver && wave > 0) {
         const mission = MISSIONS[missionIndex];
         if (mission) {
             let completed = false;
             if (mission.targetType === 'WAVE' && wave >= mission.targetValue) completed = true;
             if (mission.targetType === 'SCORE' && score >= mission.targetValue) completed = true;
             if (mission.targetType === 'COINS' && coins >= mission.targetValue) completed = true;
             if (completed) {
                 const newIndex = Persistence.completeMission();
                 setMissionIndex(newIndex);
             }
         }
     }
  }, [wave, score, coins, missionIndex, gameStarted, isGameOver]);

  const handleGraphicsSuggestionClick = () => {
      setGraphicsSuggestion(false);
      Persistence.acknowledgeGraphicsSuggestion();
      setHasSeenGraphicsSuggestion(true);
      setView('SETTINGS');
      setPreviousView('GAME');
  };

  const handleHealthStateChange = useCallback((newHp: number, newMaxHp: number) => {
    setHealth(newHp);
    setMaxHealth(newMaxHp);
  }, []);

  return (
    <div className="relative w-full h-full overflow-hidden bg-slate-950 select-none touch-none">
      {!gameStarted && !tutorialSuccess && view === 'GAME' && (
          <StartScreen 
              onStart={(floor) => { setIsTutorialRun(false); handleStart(floor); }}
              onOpenShop={() => { setView('SHOP'); setPreviousView('GAME'); }}
              onOpenSettings={() => { setView('SETTINGS'); setPreviousView('GAME'); }}
              onOpenManual={() => { setView('MANUAL'); setPreviousView('GAME'); }}
              onPlayTutorial={startTutorialRun}
              onDifficultyChange={setDifficulty}
              gameMode={gameMode}
              difficulty={difficulty}
              towerFloors={towerFloors}
          />
      )}

      {tutorialSuccess && (
          <TutorialSuccessScreen onMainMenu={() => setTutorialSuccess(false)} />
      )}

      {showEscapeTutorial && (
          <EscapeTutorialOverlay onDismiss={handleDismissEscapeTutorial} />
      )}

      {showTowerTutorial && (
          <TowerTutorialOverlay onDismiss={handleDismissTowerTutorial} />
      )}

      <GameCanvas
        onHealthChange={handleHealthStateChange}
        onScoreChange={setScore}
        onWaveChange={setWave}
        onShapeChange={setCurrentShape}
        onBuffsChange={setActiveBuffs}
        onUltChargeChange={setUltCharge}
        onBossHealthChange={(cur, max, name) => setBossHealth({current: cur, max, name})}
        onGameOver={handleGameOver}
        onGameWin={handleGameWin}
        isGameOver={isGameOver}
        isPaused={isPaused}
        gameStarted={gameStarted}
        isSlowMo={isSlowMo}
        ultTrigger={ultTrigger}
        restartTrigger={restartTrigger}
        equipped={equipped}
        upgrades={upgrades}
        moveInput={moveInput}
        aimInput={aimInput}
        requestedShape={requestedShape}
        onShapeRequestProcessed={handleShapeRequestProcessed}
        onTutorialMode={setTutorialMode}
        onTutorialComplete={handleTutorialComplete}
        onTutorialSuccess={handleTutorialSuccess}
        onPlayerAimed={handlePlayerAimed}
        onTutorialHighlight={setTutorialHighlight}
        onTutorialUltHighlight={setTutorialUltHighlight}
        isTutorialRun={isTutorialRun}
        wave={wave}
        difficulty={difficulty}
        gameMode={gameMode}
        onEscapeTimerChange={setEscapeTimer}
        onOpenMiniShop={() => { setIsPaused(true); setShowMiniShop(true); }}
        onAddCoins={handleAddCoins}
        triggerDash={triggerDash}
        triggerShield={triggerShield}
        isSlowMoHeld={isSlowMoHeld}
        onEscapeStateChange={setEscapeState}
        graphics={settings.graphics}
        playerHasMoved={playerHasMoved}
        playerHasAimed={playerHasAimed}
        showAimHintTrigger={showAimHintTrigger}
        autoFirePC={settings.autoFirePC}
        isTouchDevice={isTouchDevice}
      />

      {gameStarted && !isGameOver && !tutorialSuccess && (
        <>
            {isTouchDevice && (
                <MobileControls 
                    onMoveChange={(v) => { 
                        setMoveInput(v); 
                        if (v.active) setPlayerHasMoved(true); 
                    }} 
                    onAimChange={(v) => {
                        setAimInput(v);
                        if (v.active) setPlayerHasAimed(true);
                    }}
                    ultCharge={ultCharge}
                    onActivateUlt={() => setUltTrigger(prev => prev + 1)}
                    settings={settings}
                    gameMode={gameMode}
                    isPaused={isPaused}
                    onDash={() => setTriggerDash(prev => prev + 1)}
                    onShield={() => setTriggerShield(prev => prev + 1)}
                    onSlowMoStart={() => setIsSlowMoHeld(true)}
                    // Fixed line: replaced setIsSlowMoEnd() with setIsSlowMoHeld(false)
                    onSlowMoEnd={() => setIsSlowMoHeld(false)}
                    escapeState={escapeState}
                    glowMoveJoystick={wave === 0 && !playerHasMoved}
                    glowAimJoystick={wave === 0 && showAimHintTrigger && !playerHasAimed}
                    glowUlt={tutorialUltHighlight}
                />
            )}
            <HUD
                health={health}
                maxHealth={maxHealth}
                score={score}
                wave={wave}
                currentShape={currentShape}
                activeBuffs={activeBuffs}
                ultCharge={ultCharge}
                bossHealth={bossHealth}
                isPaused={isPaused}
                onTogglePause={handlePause}
                isSlowMo={isSlowMo}
                onToggleSlowMo={() => setIsSlowMo(!isSlowMo)}
                onActivateUltimate={() => setUltTrigger(prev => prev + 1)}
                onRestart={handleRestart}
                onQuit={handleQuit}
                unlockedShapes={[ShapeType.CIRCLE, ShapeType.SQUARE, ShapeType.TRIANGLE]}
                coins={coins}
                onOpenShop={() => { setView('SHOP'); setPreviousView('GAME'); }}
                onOpenUpgrades={() => { setView('UPGRADES'); setPreviousView('GAME'); }}
                onOpenSettings={() => { setView('SETTINGS'); setPreviousView('GAME'); setIsPaused(true); }}
                onOpenManual={() => { setView('MANUAL'); setPreviousView('GAME'); setIsPaused(true); }}
                onShapeSelect={setRequestedShape}
                equippedUltimate={equipped?.ultimates[currentShape]}
                highlightShapes={tutorialMode}
                tutorialHighlight={tutorialHighlight}
                highlightUlt={tutorialUltHighlight}
                onSkipTutorial={() => { if (isTutorialRun) { handleTutorialSuccess(); } else { setWave(1); } }}
                canSkipTutorial={wave === 0 && tutorialCompleted}
                gameMode={gameMode}
                escapeTimer={gameMode === GameMode.ESCAPE ? escapeTimer : undefined}
                escapeState={escapeState}
                activeMission={MISSIONS[missionIndex]}
                themeAnomaly={themeAnomaly && !hasSeenThemeAnomaly && !gameStarted}
                onThemeAnomalyClick={() => {
                     setThemeAnomaly(false);
                     Persistence.acknowledgeThemeAnomaly();
                     setHasSeenThemeAnomaly(true);
                     setShopInitialTab('THEMES');
                     setView('SHOP');
                     setPreviousView('GAME');
                }}
                autoFirePC={settings.autoFirePC}
                onToggleAutoFirePC={handleToggleAutoFirePC}
                isTouchDevice={isTouchDevice}
                settings={settings}
            />
        </>
      )}

      {isGameOver && (
        <GameOverScreen 
            score={score} 
            wave={wave} 
            coinsEarned={score > 0 ? Math.floor((score / 50)) : 0} 
            onRestart={handleRestart}
            onOpenShop={() => { setView('SHOP'); setPreviousView('GAME'); }}
            onOpenUpgrades={() => { setView('UPGRADES'); setPreviousView('GAME'); }}
            onMainMenu={handleQuit}
            onOpenLeaderboard={() => { setView('LEADERBOARD'); setPreviousView('GAME'); }}
            gameMode={gameMode}
        />
      )}

      {view === 'SHOP' && equipped && (
        <Shop 
            coins={coins}
            unlockedItems={unlockedItems}
            onClose={() => setView(previousView)}
            onBuy={handleBuy}
            onEquip={handleEquip}
            equipped={equipped}
            initialTab={shopInitialTab}
        />
      )}

      {view === 'UPGRADES' && upgrades && (
        <UpgradeMenu 
            coins={coins}
            onClose={() => setView(previousView)}
            upgrades={upgrades}
            onUpgrade={handleUpgrade}
        />
      )}

      {view === 'SETTINGS' && (
          <SettingsMenu 
              settings={settings} 
              onUpdateSettings={handleUpdateSettings} 
              onClose={() => setView(previousView)} 
              onResetProgress={handleResetProgress}
          />
      )}

      {view === 'MANUAL' && (
          <Manual onClose={() => setView(previousView)} />
      )}

      {view === 'LEADERBOARD' && (
          <Leaderboard onClose={() => setView(previousView)} />
      )}

      {showMiniShop && (
          <MiniShop onSelect={(type) => {
               if (type === 'HEAL') setHealth(h => Math.min(maxHealth, h + maxHealth * 0.5));
               setShowMiniShop(false);
               setIsPaused(false);
          }} />
      )}
    </div>
  );
};

