  SHAPE_CIRCLE: ['q', 'Q'],
  SHAPE_SQUARE: ['e', 'E'],
  SHAPE_TRIANGLE: ['r', 'R'],
  ULTIMATE: [' '], 
};

import React, { useEffect, useState, useRef } from 'react';
import { ShapeType, ItemType, UltimateType, GameMode, Mission, ThemeType, GameSettings } from '../types';
import { SHAPE_CONFIG, ITEM_CONFIG, ESCAPE_DASH_COOLDOWN, ESCAPE_SHIELD_COOLDOWN, ESCAPE_SLOWMO_MAX_CHARGE, ULTIMATE_CONFIG, ESCAPE_SHIELD_DURATION } from '../constants';
import { Circle, Square, Triangle, Heart, Zap, Wind, Hourglass, Sword, Pause, Play, Snail, Menu, Coins, Shield, Lock as LockIcon, Anchor, RefreshCcw, Aperture, Ghost, MoveRight, Flame, Layers, RotateCcw, Settings, FastForward, Activity, TowerControl as Tower, LocateFixed, Copy, BookOpen, ShoppingCart, LogOut, SkipForward, Timer, Flag, CheckCircle, TreeDeciduous, Moon, Snowflake, Cpu, Trees, CloudLightning, Sun, Sparkles, Laptop, Diamond, LayoutGrid, Palette, Target as Crosshair, ArrowUpCircle } from 'lucide-react';
import { SoundManager } from '../audio';

interface HUDProps {
  health: number;
  maxHealth: number;
  score: number;
  wave: number;
  currentShape: ShapeType;
  activeBuffs: { type: ItemType; time: number }[];
  ultCharge: number;
  bossHealth: { current: number; max: number; name: string | null };
  isPaused: boolean;
  onTogglePause: () => void;
  isSlowMo: boolean;
  onToggleSlowMo: () => void;
  onActivateUltimate: () => void;
  onRestart: () => void;
  onQuit: () => void;
  unlockedShapes?: ShapeType[];
  coins?: number;
  onOpenShop?: () => void;
  onOpenUpgrades?: () => void;
  onOpenSettings: () => void; 
  onOpenManual: () => void; 
  onShapeSelect: (shape: ShapeType) => void;
  equippedUltimate?: UltimateType;
  highlightShapes?: boolean;
  tutorialHighlight?: ShapeType | null; 
  highlightUlt?: boolean; 
  onSkipTutorial?: () => void;
  canSkipTutorial?: boolean;
  gameMode?: GameMode;
  escapeTimer?: number;
  escapeState?: { dashCooldown: number, shieldCooldown: number, slowMoCharge: number };
  activeMission?: Mission;
  themeAnomaly?: boolean;
  onThemeAnomalyClick?: () => void;
  autoFirePC?: boolean;
  onToggleAutoFirePC?: () => void;
  isTouchDevice?: boolean;
  settings?: GameSettings;
}

const HUD: React.FC<HUDProps> = ({
  health,
  maxHealth,
  score,
  wave,
  currentShape,
  activeBuffs,
  ultCharge,
  bossHealth,
  isPaused,
  onTogglePause,
  isSlowMo,
  onToggleSlowMo,
  onActivateUltimate,
  onRestart,
  onQuit,
  unlockedShapes = [ShapeType.CIRCLE, ShapeType.SQUARE, ShapeType.TRIANGLE],
  coins = 0,
  onOpenShop,
  onOpenUpgrades,
  onOpenSettings,
  onOpenManual,
  onShapeSelect,
  equippedUltimate,
  highlightShapes = false,
  tutorialHighlight,
  highlightUlt = false,
  onSkipTutorial,
  canSkipTutorial = false,
  gameMode,
  escapeTimer,
  escapeState,
  activeMission,
  themeAnomaly,
  onThemeAnomalyClick,
  autoFirePC,
  onToggleAutoFirePC,
  isTouchDevice = false,
  settings
}) => {
  const [hudScale, setHudScale] = useState(1);

  const isMinimal = settings?.minimalAndroidHUD;
  const shouldHideDetails = settings?.hideHudDetails;

  useEffect(() => {
    const updateScale = () => {
      const width = window.innerWidth;
      const height = window.innerHeight;
      const baseScale = Math.max(0.8, width / 1400); 
      const heightLimit = height < 600 ? (height / 600) : 1;
      setHudScale(Math.min(baseScale * heightLimit, isTouchDevice ? 1.2 : 1.05));
    };
    updateScale();
    window.addEventListener('resize', updateScale);
    return () => window.removeEventListener('resize', updateScale);
  }, [isTouchDevice]);

  const healthPercentage = Math.max(0, (health / maxHealth) * 100);

  const getShapeIcon = (shape: ShapeType) => {
      const iconSize = "w-8 h-8 md:w-9 md:h-9"; 
      switch(shape) {
          case ShapeType.CIRCLE: return <Circle className={`text-white ${iconSize}`} />;
          case ShapeType.SQUARE: return <Square className={`text-white ${iconSize}`} />;
          case ShapeType.TRIANGLE: return <Triangle className={`text-white ${iconSize} mt-0.5 md:mt-1`} />;
      }
  };

  const getShapeName = (shape: ShapeType) => {
      switch(shape) {
          case ShapeType.CIRCLE: return "SPEED";
          case ShapeType.SQUARE: return "GUARD";
          case ShapeType.TRIANGLE: return "ATTACK";
      }
  };

  const getShapeKey = (shape: ShapeType) => {
    switch(shape) {
        case ShapeType.CIRCLE: return "Q";
        case ShapeType.SQUARE: return "E";
        case ShapeType.TRIANGLE: return "R";
    }
  };

  const getShapeClass = (shape: ShapeType) => {
    const isActive = currentShape === shape;
    const isHighlighted = tutorialHighlight === shape;
    const padding = "p-3 md:p-3.5"; 
    const minWidth = "min-w-[80px] md:min-w-[95px]"; 
    const base = `flex flex-col items-center justify-center ${padding} rounded-2xl transition-all duration-300 outline-none touch-manipulation relative overflow-hidden ${minWidth}`;

    let stateClass = "border border-transparent opacity-60 scale-100 active:scale-95 hover:bg-slate-800/40";

    if (isActive) {
      stateClass = `border-2 border-white/40 bg-white/10 scale-105 shadow-[0_0_20px_rgba(255,255,255,0.15)] backdrop-blur-md z-10`;
    } else if (isHighlighted) {
      stateClass = `border-4 border-yellow-400 bg-yellow-500/20 scale-110 shadow-[0_0_30px_rgba(234,179,8,0.6)] animate-pulse z-20 opacity-100`;
    }

    return `${base} ${stateClass}`;
  };

  const [displayHealth, setDisplayHealth] = useState(health);
  const lastUpdateRef = useRef<number>(performance.now());

  useEffect(() => {
    let animationFrame: number;
    const animate = () => {
        const now = performance.now();
        const dt = (now - lastUpdateRef.current) / 1000;
        lastUpdateRef.current = now;

        setDisplayHealth(prev => {
            const diff = health - prev;
            if (Math.abs(diff) < 0.1) return health;
            // Use time-based approach factor (Hz independent)
            const factor = 1 - Math.exp(-6 * dt);
            return prev + diff * factor;
        });
        animationFrame = requestAnimationFrame(animate);
    };
    animate();
    return () => cancelAnimationFrame(animationFrame);
  }, [health]);

  const displayHealthPercent = (displayHealth / maxHealth) * 100;
  const isLowHealth = healthPercentage < 30;

  let healthColor = "bg-emerald-500";
  if (healthPercentage < 50) healthColor = "bg-yellow-400";
  if (healthPercentage < 25) healthColor = "bg-rose-600";

  const showTopBar = wave > 0 || tutorialHighlight !== undefined || highlightUlt; 

  const utilityBtnSize = "p-2.5 md:p-3";
  const utilityIconSize = "w-5 h-5 md:w-6 md:h-6";

  const readoutOpacity = shouldHideDetails ? 'opacity-0 pointer-events-none' : (isMinimal && wave > 0) ? 'opacity-20 translate-y-[-5px]' : 'opacity-100';
  const readoutTransform = isMinimal ? 'scale-90' : 'scale-100';

  const renderSkillBars = () => {
      if (shouldHideDetails) return null;

      const bars = [];

      if (gameMode === GameMode.ESCAPE && escapeState) {
          const dashPct = Math.max(0, 100 - (escapeState.dashCooldown / ESCAPE_DASH_COOLDOWN) * 100);
          bars.push(
              <div key="dash" className="flex items-center gap-2 group">
                  <Wind size={12} className={`shrink-0 ${dashPct < 100 ? 'text-slate-500' : 'text-cyan-400 animate-pulse'}`} />
                  <div className="flex-1 h-1 bg-slate-900/60 rounded-full border border-slate-800 overflow-hidden relative">
                      <div 
                          className={`h-full transition-all duration-300 ${dashPct < 100 ? 'bg-cyan-900/60' : 'bg-cyan-500 shadow-[0_0_8px_#22d3ee]'}`} 
                          style={{ width: `${dashPct}%` }} 
                      />
                  </div>
                  {!isTouchDevice && <span className="text-[7px] font-black text-slate-500 font-mono w-6 text-center">SHIFT</span>}
              </div>
          );

          const shieldPct = Math.max(0, 100 - (escapeState.shieldCooldown / ESCAPE_SHIELD_COOLDOWN) * 100);
          bars.push(
              <div key="shield" className="flex items-center gap-2 group">
                  <Shield size={12} className={`shrink-0 ${shieldPct < 100 ? 'text-slate-500' : 'text-blue-400 animate-pulse'}`} />
                  <div className="flex-1 h-1 bg-slate-900/60 rounded-full border border-slate-800 overflow-hidden relative">
                      <div 
                          className={`h-full transition-all duration-300 ${shieldPct < 100 ? 'bg-blue-900/60' : 'bg-blue-500 shadow-[0_0_8px_#3b82f6]'}`} 
                          style={{ width: `${shieldPct}%` }} 
                      />
                  </div>
                  {!isTouchDevice && <span className="text-[7px] font-black text-slate-500 font-mono w-6 text-center">F</span>}
              </div>
          );

          bars.push(
            <div key="slowmo-charge" className="flex items-center gap-2 group">
                <Hourglass size={12} className={`shrink-0 ${escapeState.slowMoCharge <= 0 ? 'text-slate-500' : 'text-purple-400 animate-pulse'}`} />
                <div className="flex-1 h-1 bg-slate-900/60 rounded-full border border-slate-800 overflow-hidden relative">
                    <div 
                        className={`h-full transition-all duration-75 ${escapeState.slowMoCharge <= 0 ? 'bg-purple-900/60' : 'bg-purple-500 shadow-[0_0_8px_#a855f7]'}`} 
                        style={{ width: `${escapeState.slowMoCharge}%` }} 
                    />
                </div>
                {!isTouchDevice && <span className="text-[7px] font-black text-slate-500 font-mono w-6 text-center">C</span>}
            </div>
          );
      }

      activeBuffs.forEach((buff, idx) => {
          const config = ITEM_CONFIG[buff.type];
          const durationPct = (buff.time / config.duration) * 100;
          let Icon = Zap;
          if (buff.type === ItemType.POWER) Icon = Sword;
          if (buff.type === ItemType.SLOW) Icon = Hourglass;
          if (buff.type === ItemType.SPEED) Icon = Zap;

          bars.push(
              <div key={`buff-${buff.type}`} className="flex items-center gap-2 animate-in slide-in-from-left-2 duration-300">
                  <Icon size={12} style={{ color: config.color }} className="shrink-0" />
                  <div className="flex-1 h-1 bg-slate-900/60 rounded-full border border-slate-800 overflow-hidden">
                      <div 
                          className="h-full transition-all duration-100 linear" 
                          style={{ width: `${durationPct}%`, backgroundColor: config.color, boxShadow: `0 0 10px ${config.color}88` }} 
                      />
                  </div>
              </div>
          );
      });

      if (bars.length === 0) return null;

      return (
          <div className="flex flex-col gap-1.5 mt-2.5 w-32 md:w-48 transition-all duration-500">
              {bars}
          </div>
      );
  };

  return (
    <div 
        className="absolute inset-0 pointer-events-none z-50 flex flex-col justify-between select-none"
        style={{
            paddingTop: 'calc(0.75rem + var(--safe-top))',
            paddingLeft: 'calc(1rem + var(--safe-left))',
            paddingRight: 'calc(1rem + var(--safe-right))',
            paddingBottom: 'calc(0.75rem + var(--safe-bottom))',
        }}
    >
      {isPaused && (
         <div className="absolute inset-0 z-[60] flex items-center justify-center bg-slate-950/90 backdrop-blur-xl pointer-events-auto animate-in fade-in duration-200">
             <div 
                className="bg-slate-900 border border-slate-700 p-8 rounded-2xl shadow-2xl flex flex-col gap-3 min-w-[300px] max-w-sm w-full animate-in zoom-in-95 duration-200"
                style={{ transform: `scale(${hudScale})` }}
             >
                 <h2 className="text-2xl md:text-3xl font-black text-white text-center mb-4 tracking-widest uppercase">Paused</h2>
                 <button onClick={onTogglePause} className="flex flex-col items-center justify-center w-full py-3.5 bg-white text-slate-900 font-bold rounded-xl hover:bg-slate-200 active:scale-95 transition-all shadow-lg">
                    <div className="flex items-center gap-3">
                        <Play size={22} fill="currentColor" /> RESUME
                    </div>
                    {!isTouchDevice && <span className="text-[8px] font-mono mt-1 opacity-60">[P]</span>}
                 </button>
                 <div className="grid grid-cols-1 gap-2">
                     {onOpenShop && (
                        <button onClick={onOpenShop} disabled={gameMode === GameMode.ESCAPE} className={`flex items-center justify-center gap-2 py-3 bg-slate-800 text-slate-300 font-bold rounded-xl border border-slate-700 hover:bg-slate-700 hover:text-white active:scale-95 transition-all ${gameMode === GameMode.ESCAPE ? 'opacity-50 cursor-not-allowed' : ''}`}>
                            <ShoppingCart size={18} />
                            <span className="text-[10px] uppercase">Armory</span>
                        </button>
                     )}
                 </div>
                 <button onClick={() => { SoundManager.playClick(); onRestart(); }} className="flex items-center justify-center gap-3 w-full py-3.5 bg-slate-800 text-slate-200 font-bold rounded-xl border border-slate-700 hover:bg-slate-700 active:scale-95 transition-all">
                     <RotateCcw size={18} /> RESTART MISSION
                 </button>
                 <button onClick={onQuit} className="flex items-center justify-center gap-3 w-full py-3.5 bg-red-900/20 text-red-400 font-bold rounded-xl border border-red-900/30 hover:bg-red-900/40 hover:text-red-300 active:scale-95 transition-all mt-2">
                     <LogOut size={18} /> QUIT TO TITLE
                 </button>
             </div>
         </div>
      )}

      <div className={`flex justify-between items-start pointer-events-auto transition-opacity duration-1000 ${showTopBar ? 'opacity-100' : 'opacity-0'}`}>
        <div 
          className={`flex flex-col transition-all duration-500 ${readoutOpacity} ${readoutTransform}`}
          style={{ transform: `scale(${hudScale})`, transformOrigin: 'top left' }}
        >
           <div className="flex flex-col w-44 md:w-64 gap-1.5">
                <div className="flex gap-2">
                    <div className="flex-1 flex flex-col justify-center">
                        <div className="flex items-center gap-2 text-white font-black text-[10px] md:text-lg shadow-black drop-shadow-md">
                            <Heart className={`w-4 h-4 md:w-6 md:h-6 ${isLowHealth ? 'text-red-500 fill-red-500 animate-pulse' : 'text-slate-200'}`} />
                            <span>{Math.ceil(health)}</span>
                        </div>
                    </div>
                </div>
                <div className="w-full h-2 md:h-5 bg-slate-900/80 rounded-full overflow-hidden border-2 border-slate-700 relative shadow-lg">
                    <div className="absolute top-0 left-0 h-full bg-white transition-all duration-300 ease-out" style={{ width: `${displayHealthPercent}%` }} />
                    <div className={`absolute top-0 left-0 h-full transition-all duration-75 ${healthColor} ${isLowHealth ? 'animate-pulse' : ''}`} style={{ width: `${healthPercentage}%` }} />
                </div>
           </div>

           {renderSkillBars()}
        </div>

        <div 
          className={`absolute left-1/2 -translate-x-1/2 top-3 flex flex-col items-center pointer-events-none z-30 transition-all duration-500 ${isMinimal ? 'opacity-40 scale-75' : 'opacity-100'}`}
          style={{ transform: `translateX(-50%) scale(${hudScale})`, transformOrigin: 'top center' }}
        >
            {gameMode === GameMode.ESCAPE && escapeTimer !== undefined ? (
                <div className="flex flex-col items-center animate-in fade-in zoom-in duration-500">
                    <div className="flex items-center gap-2 bg-slate-900/80 backdrop-blur px-3 py-1 md:px-4 md:py-2 rounded-full border border-red-500/50 shadow-lg shadow-red-900/30">
                        <Timer className={`w-4 h-4 md:w-5 md:h-5 ${escapeTimer < 10 ? 'text-red-500 animate-pulse' : 'text-slate-300'}`} />
                        <span className={`text-lg md:text-xl font-black font-mono tracking-widest ${escapeTimer < 10 ? 'text-red-500' : 'text-white'}`}>{escapeTimer.toFixed(1)}s</span>
                    </div>
                </div>
            ) : null}
        </div>

        {bossHealth.name && gameMode !== GameMode.ESCAPE && (
            <div 
              className={`absolute left-1/2 -translate-x-1/2 top-12 md:top-20 w-2/3 md:w-1/3 flex flex-col items-center animate-in fade-in zoom-in duration-500 pointer-events-none transition-all duration-500 ${isMinimal ? 'opacity-40' : 'opacity-100'}`}
              style={{ transform: `translateX(-50%) scale(${hudScale})`, transformOrigin: 'top center' }}
            >
                 <h2 className="text-red-500 font-black text-[10px] md:text-lg tracking-widest uppercase drop-shadow-lg mb-1 animate-pulse text-center">{bossHealth.name}</h2>
                 <div className="w-full h-2 md:h-5 bg-slate-900 rounded-full border border-red-900 overflow-hidden relative shadow-[0_0_20px_rgba(220,38,38,0.5)]">
                     <div className="h-full bg-red-600 transition-all duration-100" style={{ width: `${(bossHealth.current / bossHealth.max) * 100}%` }} />
                 </div>
            </div>
        )}

        <div 
          className="text-right flex flex-col items-end gap-1"
          style={{ transform: `scale(${hudScale})`, transformOrigin: 'top right' }}
        >
          <div className="flex gap-2 md:gap-2.5 mb-1">
               <div className={`flex gap-2 transition-all duration-500 ${readoutOpacity}`}>
                    {!isTouchDevice && onToggleAutoFirePC && (
                        <button onPointerDown={(e) => { e.stopPropagation(); onToggleAutoFirePC(); }} className={`relative ${utilityBtnSize} rounded-xl border-2 transition-all hover:scale-105 active:scale-95 touch-manipulation ${autoFirePC ? 'bg-cyan-600 border-cyan-400 text-white shadow-[0_0_10px_rgba(6,182,212,0.5)]' : 'bg-slate-800 border-slate-600 text-slate-400'}`} title={autoFirePC ? "Auto-fire ON (PC)" : "Auto-fire OFF (PC)"}>
                            <Crosshair className={utilityIconSize} />
                        </button>
                    )}
                    {gameMode !== GameMode.ESCAPE && (
                        <button onPointerDown={(e) => { e.stopPropagation(); onToggleSlowMo(); }} className={`${utilityBtnSize} rounded-xl border-2 transition-all hover:scale-105 active:scale-95 touch-manipulation ${isSlowMo ? 'bg-purple-600 border-purple-400 text-white shadow-[0_0_15px_rgba(168,85,247,0.5)]' : 'bg-slate-800 border-slate-600 text-slate-400'} shadow-lg`} title="SlowMo"><Snail className={utilityIconSize} /></button>
                    )}
               </div>
               <div className="flex flex-col items-center">
                    <button 
                        onPointerDown={(e) => { e.stopPropagation(); onTogglePause(); }} 
                        className={`${utilityBtnSize} rounded-xl border-2 transition-all hover:scale-105 active:scale-95 touch-manipulation ${isPaused ? 'bg-yellow-500 border-yellow-300 text-white shadow-[0_0_15px_rgba(234,179,8,0.5)]' : (isMinimal && wave > 0) ? 'bg-slate-900/10 border-slate-700/10 text-slate-600 opacity-10 hover:opacity-100' : 'bg-slate-800 border-slate-600 text-slate-400'} shadow-lg`} 
                        title={isPaused ? "Resume" : "Pause"}
                    >
                        {isPaused ? <Play className={utilityIconSize} /> : <Pause className={utilityIconSize} />}
                    </button>
                    {!isTouchDevice && <span className="text-[7px] font-black text-slate-500 font-mono mt-0.5 uppercase">[P]</span>}
               </div>
          </div>
          <div className={`flex flex-col items-end leading-tight transition-all duration-500 ${readoutOpacity} ${readoutTransform}`}>
            <div className="flex items-center gap-1 text-amber-400 font-bold text-[9px] md:text-lg mb-0.5"><span>{coins.toLocaleString()}</span><Coins className="w-2.5 h-2.5 md:w-4 md:h-4" /></div>
            <div className="text-xl md:text-4xl font-black text-white drop-shadow-lg tracking-tighter">{score.toLocaleString()}</div>
            <div className="text-cyan-400 font-bold text-[9px] md:text-lg tracking-widest uppercase">{getWaveText(gameMode, wave)}</div>
          </div>
        </div>
      </div>

      <div 
        className="fixed bottom-[calc(0.75rem+var(--safe-bottom))] left-1/2 flex flex-col items-center pointer-events-none z-[50]"
        style={{ transform: `translateX(-50%) scale(${hudScale})`, transformOrigin: 'bottom center' }}
      >
         {!isPaused && (wave > 0 || tutorialHighlight !== undefined || highlightUlt) && gameMode !== GameMode.ESCAPE && ((!isMinimal && !isTouchDevice) || (highlightUlt && !isTouchDevice)) && (
            <div className={`flex flex-col items-center mb-3 md:mb-5 animate-in fade-in slide-in-from-bottom-2 duration-700 ${highlightUlt ? 'scale-110' : ''}`}>
                <div className="flex justify-between w-60 md:w-64 mb-1 px-1">
                    <span className={`text-[8px] md:text-[9px] font-black tracking-[0.2em] transition-colors ${ultCharge >= 100 ? 'text-yellow-400 animate-pulse' : 'text-slate-500 uppercase'} ${highlightUlt ? 'text-white drop-shadow-[0_0_8px_#fbbf24]' : ''}`}>
                        {highlightUlt && ultCharge >= 100 ? 'SYSTEM READY: ACTIVATE ULTIMATE' : ultCharge >= 100 ? 'ULTIMATE READY' : 'RECHARGING'}
                    </span>
                    <span className="text-[8px] md:text-[9px] font-mono font-bold text-slate-500">{Math.floor(ultCharge)}%</span>
                </div>
                <div className={`w-60 md:w-64 h-1.5 md:h-2.5 bg-slate-900/80 rounded-full border border-slate-700 overflow-hidden relative shadow-2xl transition-all duration-500 ${highlightUlt ? 'ring-2 md:ring-3 ring-yellow-400 border-white' : ''}`}>
                    <div className={`h-full transition-all duration-300 ease-out relative ${ultCharge >= 100 ? 'bg-yellow-400 shadow-[0_0_25px_rgba(234,179,8,0.6)]' : 'bg-gradient-to-r from-cyan-600 to-cyan-400'}`} style={{ width: `${ultCharge}%` }} />
                </div>
                {!isTouchDevice && (
                    <div className="text-[8px] font-mono text-slate-500 mt-1 uppercase tracking-widest font-black">[SPACE]</div>
                )}
            </div>
         )}

         {!isPaused && (
             <div className="flex justify-center items-end gap-2 md:gap-4">
                {unlockedShapes.map(shape => (
                     <div key={shape} className="flex flex-col items-center">
                        <button 
                            onPointerDown={(e) => { 
                                e.stopPropagation(); 
                                if (navigator.vibrate) navigator.vibrate(20);
                                onShapeSelect(shape); 
                            }}
                            className={`pointer-events-auto ${getShapeClass(shape)}`}
                        >
                            <div className={`${SHAPE_CONFIG[shape].uiColor} p-3 md:p-4 rounded-xl mb-1 md:mb-1.5 shadow-lg pointer-events-none`}>
                                {getShapeIcon(shape)}
                            </div>
                            <span className={`text-[9px] md:text-xs font-black pointer-events-none ${currentShape === shape ? 'text-white' : 'text-slate-400'}`}>
                                {getShapeName(shape)}
                            </span>
                        </button>
                        {!isTouchDevice && (
                            <div className="text-[9px] font-black font-mono text-slate-600 mt-1 uppercase">[{getShapeKey(shape)}]</div>
                        )}
                     </div>
                ))}
             </div>
         )}
      </div>
    </div>
  );
};

function getWaveText(gameMode: GameMode | undefined, wave: number) {
    if (gameMode === GameMode.TOWER) return `Floor ${wave}`;
    if (gameMode === GameMode.ESCAPE) return `Zone ${wave}`;
    if (wave === 0) return "TUTORIAL";
    return `Wave ${wave}`;
}

