  const createEnemy = (type: EnemyType, x: number, y: number, wave: number, isBoss: boolean = false, isSafe: boolean = false): Enemy => {
    const config = ENEMY_TYPES_CONFIG[type];
    const diff = DIFFICULTY_CONFIG[difficulty || Difficulty.NORMAL];
    let health, damage, speed, attackCooldown;

    const baseCooldown = (config as any).attackCooldown || 1.0;
    const waveScaling = wave > 0 ? (1 / (1 + wave * 0.04)) : 1.0;
    attackCooldown = baseCooldown * diff.attackCooldownMult * waveScaling;

    if (type === EnemyType.DUMMY_TARGET) { health = 50; damage = 0; speed = 0; }
    else if (gameMode === GameMode.ESCAPE) {
        const speedGrowth = 1 + (wave * 0.08);
        if (type === EnemyType.RUNNER) speed = 240 * speedGrowth * diff.speedMult; 
        else if (type === EnemyType.SHOOTER) speed = 50 * speedGrowth * diff.speedMult;
        else speed = config.speed * speedGrowth * diff.speedMult;
        health = 1; damage = config.damage * diff.dmgMult;
    } else if (isBoss) {
        const bossScalingFactor = difficulty === Difficulty.EASY ? 0.15 : (difficulty === Difficulty.NORMAL ? 0.35 : 0.5);
        health = config.health * (1 + (wave - 1) * bossScalingFactor) * diff.hpMult; 
        damage = (config.damage + (wave * 1.5)) * diff.dmgMult; 
        speed = (config.speed + (wave * 1.2)) * diff.speedMult; 
        attackCooldown *= (1 / (1 + wave * 0.05));
    } else {
        let effectiveWave = wave, speedWave = wave;
        const isHard = difficulty === Difficulty.HARD;
        const capWave = isHard ? 6 : 4;
        if (wave > capWave) {
            const hpGrowth = isHard ? 0.6 : 0.4;
            const speedGrowth = isHard ? 0.25 : 0.15;
            effectiveWave = capWave + (wave - capWave) * hpGrowth; 
            speedWave = capWave + (wave - capWave) * speedGrowth;    
        }
        health = (config.health + (effectiveWave * 1.2)) * diff.hpMult; 
        damage = (config.damage + (effectiveWave * 0.15)) * diff.dmgMult; 
        speed = (config.speed + (speedWave * 0.4)) * diff.speedMult;   
    }
    if (isSafe) { damage = 0; speed *= 0.5; health = 1; }
    else if (wave === 0) { 
        if (type === EnemyType.SWARM) { health = 1; damage = 1; }
        else if (type === EnemyType.TANK) { health = 60; damage = 5; }
        else { damage = 5 * diff.dmgMult; speed *= 0.8 * diff.speedMult; }
    }

    return {
        id: Math.random().toString(), type, position: { x, y }, velocity: { x: 0, y: 0 }, 
        radius: config.radius * gameScale, color: config.color, rotation: 0,
        health, maxHealth: health, damage, speed, scoreValue: Math.floor(config.score * diff.scoreMult), 
        attackTimer: attackCooldown, 
        attackCooldown: attackCooldown,
        secondaryAttackTimer: 0, hitFlash: 0, stunTimer: 0, isBoss, hasSplit: false, stunMeter: 0, maxStunMeter: 100, hasEnteredScreen: false, isWave0Safe: isSafe
