      if (player.activeUltimateType === UltimateType.DEATH_RAY && gameMode !== GameMode.ESCAPE) { ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(1000, 0); ctx.lineWidth = 15 + Math.sin(timeRef.current * 20) * 5; ctx.strokeStyle = currentEnergyColor; ctx.shadowColor = currentEnergyColor; ctx.shadowBlur = 20; ctx.stroke(); ctx.lineWidth = 5; ctx.strokeStyle = '#fff'; ctx.stroke(); }
      if (player.shieldActiveTimer > 0) { ctx.beginPath(); ctx.arc(0, 0, player.radius + 15, 0, Math.PI * 2); ctx.strokeStyle = currentEnergyColor; ctx.lineWidth = 3; ctx.stroke(); ctx.fillStyle = currentEnergyColor; ctx.globalAlpha = 0.3; ctx.fill(); ctx.globalAlpha = 1.0; }
      if (player.ultActiveTimer > 0) {
           if (player.activeUltimateType === UltimateType.IRON_WALL) { ctx.save(); ctx.rotate(timeRef.current); ctx.strokeStyle = currentEnergyColor; ctx.lineWidth = 3; ctx.beginPath(); for (let i = 0; i <= 6; i++) { const a = i * 2 * Math.PI / 6; if (i === 0) ctx.moveTo((player.radius+20)*Math.cos(a), (player.radius+20)*Math.sin(a)); else ctx.lineTo((player.radius+20)*Math.cos(a), (player.radius+20)*Math.sin(a)); } ctx.closePath(); ctx.stroke(); ctx.globalAlpha = 0.2; ctx.fillStyle = currentEnergyColor; ctx.fill(); ctx.restore(); }
           else if (player.activeUltimateType === UltimateType.BLADE_STORM) { const speed = timeRef.current * 10; for(let i=0; i<6; i++) { const a = (Math.PI*2/6)*i + speed; drawBlade(ctx, Math.cos(a)*(player.radius+30), Math.sin(a)*(player.radius+30), a, currentEnergyColor); } }
           else if (player.activeUltimateType === UltimateType.HYPER_DASH) { ctx.fillStyle = currentEnergyColor; ctx.globalAlpha = 0.3; ctx.beginPath(); ctx.moveTo(-player.radius*3, 0); ctx.lineTo(0, player.radius); ctx.lineTo(0, -player.radius); ctx.fill(); ctx.globalAlpha = 1.0; }
           else if (player.activeUltimateType === UltimateType.TIME_WARP) { ctx.strokeStyle = currentEnergyColor; ctx.lineWidth = 2; ctx.beginPath(); ctx.arc(0, 0, player.radius * 4, 0, Math.PI*2); ctx.stroke(); ctx.save(); ctx.rotate(timeRef.current * -5); ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(player.radius * 4, 0); ctx.stroke(); ctx.restore(); }
           else if (player.activeUltimateType === UltimateType.REFLECTIVE_SHIELD || player.activeUltimateType === UltimateType.REFLECTIVE_SHELL) { ctx.strokeStyle = currentEnergyColor; ctx.lineWidth = 2; ctx.setLineDash([5, 5]); ctx.beginPath(); ctx.arc(0,0, player.radius + 30, 0, Math.PI*2); ctx.stroke(); ctx.setLineDash([]); }
           else if (player.activeUltimateType === UltimateType.FORTRESS_MODE) { ctx.strokeStyle = currentEnergyColor; ctx.lineWidth = 5; ctx.beginPath(); ctx.arc(0, 0, player.radius + 20, 0, Math.PI*2); ctx.stroke(); ctx.save(); ctx.rotate(player.fortressAngle || 0); ctx.fillStyle = currentEnergyColor; ctx.fillRect(-10, -10, 40, 20); ctx.fillRect(-10, -10, -20, 20); ctx.restore(); }
           else if (player.activeUltimateType === UltimateType.GHOST_DASH) ctx.globalAlpha = 0.4;
      }
      if (player.isTransforming && player.previousShape) { const t = player.transformTime / player.transformDuration, smooth = t*t*(3-2*t); ctx.save(); ctx.rotate(-smooth*Math.PI/4); drawShapeBody(player.previousShape, player.radius*(1-smooth), 1-smooth, getSkinThemeColor(skin, SHAPE_CONFIG[player.previousShape].color)); ctx.restore(); ctx.save(); ctx.rotate((1-smooth)*Math.PI/4); drawShapeBody(player.shape, player.radius*smooth, smooth, currentEnergyColor); ctx.restore(); }
      else drawShapeBody(player.shape, player.radius, 1, currentEnergyColor);
      if (player.effectPower > 0) { ctx.strokeStyle = ITEM_CONFIG[ItemType.POWER].color; ctx.lineWidth = 2; ctx.beginPath(); ctx.arc(0, 0, player.radius + 8 + Math.sin(timeRef.current * 10) * 2, 0, Math.PI*2); ctx.stroke(); }
      if (player.effectSpeed > 0) { ctx.strokeStyle = ITEM_CONFIG[ItemType.SPEED].color; ctx.lineWidth = 2; ctx.beginPath(); ctx.arc(0, 0, player.radius + 5, 0, Math.PI*2); ctx.stroke(); }
      if (player.webbedTimer > 0) { ctx.strokeStyle = '#22c55e'; ctx.lineWidth = 3; ctx.beginPath(); const r = player.radius + 2; ctx.moveTo(-r, -r/2); ctx.lineTo(r, -r/2); ctx.moveTo(-r, r/2); ctx.lineTo(r, r/2); ctx.moveTo(-r/2, -r); ctx.lineTo(-r/2, r); ctx.moveTo(r/2, -r); ctx.lineTo(r/2, r); ctx.stroke(); }
      if (player.stunnedTimer > 0) { ctx.fillStyle = '#eab308'; for(let i=0; i<3; i++) { const a = timeRef.current*5 + (Math.PI*2/3)*i, r = player.radius+10; ctx.beginPath(); ctx.arc(Math.cos(a)*r, Math.sin(a)*r, 4, 0, Math.PI*2); ctx.fill(); } }
      ctx.restore(); 

      if (towerTransitionRef.current.active) {
          const { phase, timer } = towerTransitionRef.current;
          ctx.save();
          if (phase === 'OUT') {
              const progress = timer / 1.5;
              ctx.strokeStyle = player.color;
              ctx.lineWidth = 10 + progress * 50;
              ctx.globalAlpha = 1 - progress;
              ctx.beginPath();
              ctx.arc(width/2, height/2, progress * width * 0.8, 0, Math.PI * 2);
              ctx.stroke();

              ctx.fillStyle = '#000';
              ctx.globalAlpha = progress * 0.6;
              ctx.fillRect(0, 0, width, height);

              ctx.globalAlpha = progress * 0.4;
              ctx.strokeStyle = '#fff';
              ctx.lineWidth = 2;
              for(let i=0; i<8; i++) {
                  const angle = (Math.PI*2/8)*i + timeRef.current;
                  ctx.beginPath();
                  ctx.moveTo(width/2 + Math.cos(angle)*100, height/2 + Math.sin(angle)*100);
                  ctx.lineTo(width/2 + Math.cos(angle)*width, height/2 + Math.sin(angle)*width);
                  ctx.stroke();
              }
          } else {
              const progress = timer / 1.0;
              ctx.strokeStyle = player.color;
              ctx.lineWidth = 5;
              ctx.globalAlpha = 1 - progress;
              ctx.beginPath();
              ctx.arc(width/2, height/2, (1-progress) * 200, 0, Math.PI * 2);
              ctx.stroke();
          }
          ctx.restore();
      }

      floatingTextsRef.current.forEach(ft => { ctx.save(); ctx.translate(ft.position.x, ft.position.y); ctx.globalAlpha = ft.life / ft.maxLife; ctx.fillStyle = ft.color; ctx.strokeStyle = '#000'; ctx.lineWidth = 2; ctx.font = `bold ${16 * ft.scale}px sans-serif`; ctx.textAlign = 'center'; ctx.strokeText(ft.text, 0, 0); ctx.fillText(ft.text, 0, 0); ctx.restore(); });

      if (waveRef.current === 0 && wave0FlagsRef.current.has('ult_tutorial_active') && !wave0FlagsRef.current.has('ult_used') && !isTouchDevice && isMouseDeviceRef.current && window.innerWidth >= 768) {
          ctx.save(); ctx.translate(player.position.x, player.position.y - 70 + Math.sin(timeRef.current * 4) * 8); ctx.shadowColor = '#d946ef'; ctx.shadowBlur = 15 + Math.sin(timeRef.current * 10) * 10; ctx.fillStyle = 'rgba(15, 23, 42, 0.9)'; ctx.strokeStyle = '#d946ef'; ctx.lineWidth = 2; const w = 100, h = 36, r = 6; ctx.beginPath(); ctx.moveTo(-w/2+r, -h/2); ctx.lineTo(w/2-r, -h/2); ctx.quadraticCurveTo(w/2, -h/2, w/2, -h/2+r); ctx.lineTo(w/2, h/2-r); ctx.quadraticCurveTo(w/2, h/2, w/2-r, h/2); ctx.lineTo(-w/2+r, h/2); ctx.quadraticCurveTo(-w/2, h/2, -w/2, h/2-r); ctx.lineTo(-w/2, -h/2+r); ctx.quadraticCurveTo(-w/2, -h/2, -w/2+r, -h/2); ctx.closePath(); ctx.fill(); ctx.stroke(); ctx.shadowBlur = 0; ctx.fillStyle = '#fff'; ctx.font = "bold 16px sans-serif"; ctx.textAlign = "center"; ctx.textBaseline = "middle"; ctx.fillText("SPACE", 0, 1); ctx.font = "bold 12px sans-serif"; ctx.fillStyle = "#d946ef"; ctx.shadowColor = 'black'; ctx.shadowBlur = 4; ctx.fillText("ULTIMATE READY", 0, -30); ctx.restore();
      }
      ctx.restore(); 
      animationFrameId = requestAnimationFrame(render);
     } catch (e) { console.error("Render error:", e); }
    };
    render(performance.now());
    return () => cancelAnimationFrame(animationFrameId);
  }, [resetGame, graphics, theme, skin, gameMode, difficulty, gameScale, playerHasMoved, playerHasAimed, showAimHintTrigger, autoFirePC, isTouchDevice, preset.bgDensity, preset.dpr, preset.enableBgParticles, preset.enableScreenShake, getSkinThemeColor]);

  return <canvas ref={canvasRef} className="block w-full h-full" style={{ touchAction: 'none' }} />;
};

