const getDistance = (v1: Vector2, v2: Vector2) => Math.hypot(v1.x - v2.x, v1.y - v2.y);
const normalize = (v: Vector2): Vector2 => {
  const mag = Math.hypot(v.x, v.y);
  return mag === 0 ? { x: 0, y: 0 } : { x: v.x / mag, y: v.y / mag };
};
const clamp = (val: number, min: number, max: number) => Math.min(Math.max(val, min), max);

const checkRaycastHit = (start: Vector2, end: Vector2, circlePos: Vector2, radius: number): boolean => {
    const dx = end.x - start.x;
    const dy = end.y - start.y;
    const lenSq = dx * dx + dy * dy;
    if (lenSq < 1) return false;
    const t = ((circlePos.x - start.x) * dx + (circlePos.y - start.y) * dy) / lenSq;
    const clampedT = Math.max(0, Math.min(1, t));
    const closestX = start.x + clampedT * dx;
    const closestY = start.y + clampedT * dy;
    const distSq = (circlePos.x - closestX) ** 2 + (circlePos.y - closestY) ** 2;
    return distSq < radius * radius;
};

const createMetalGradient = (ctx: CanvasRenderingContext2D, x: number, y: number, r: number, time: number) => {
    const angle = time * 2;
    const grad = ctx.createLinearGradient(
        x - r * Math.cos(angle), y - r * Math.sin(angle),
        x + r * Math.cos(angle), y + r * Math.sin(angle)
    );
    grad.addColorStop(0.0, '#334155');
    grad.addColorStop(0.4, '#94a3b8');
    grad.addColorStop(0.5, '#f8fafc');
    grad.addColorStop(0.6, '#94a3b8');
    grad.addColorStop(1.0, '#334155');
    return grad;
};

