        }
    };
    if (!propsRef.current.isGameOver) {
      handleResize();
      if (restartTrigger === 0 && waveRef.current === 0 && enemiesRef.current.length === 0 && wave0TimerRef.current === 0) {
          resetGame();
      }
    } else {
        SoundManager.stopMusic();
    }
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [propsRef.current.isGameOver, resetGame, graphics, isTouchDevice, preset.dpr]);

  const spawnParticles = (pos: Vector2, count: number, color: string, speed: number, life: number = 0.6, size: number = 2, type: string = 'NORMAL') => {
    const limit = preset.maxParticles;
    let themeMultiplier = (theme === ThemeType.LAVA || theme === ThemeType.STORM || theme === ThemeType.CRYSTAL || theme === ThemeType.CYBER || theme === ThemeType.HACKER) ? 0.35 : 1.0;
    const requestedCount = Math.ceil(count * themeMultiplier);
    if (particlesRef.current.length + requestedCount > limit) {
        if (particlesRef.current.length > limit) particlesRef.current.splice(0, requestedCount);
        count = Math.min(requestedCount, Math.max(0, limit - particlesRef.current.length + 10));
    } else {
        count = requestedCount;
    }
    for (let i = 0; i < count; i++) {
        const angle = Math.random() * Math.PI * 2;
        const v = (Math.random() * 0.5 + 0.5) * speed;
        let vx = Math.cos(angle) * v;
        let vy = Math.sin(angle) * v;
        if (type === 'PICKUP_SPARK') { vx = (Math.random() - 0.5) * speed * 0.5; vy = -Math.random() * speed; }
        particlesRef.current.push({
            id: 'p', position: { x: pos.x, y: pos.y }, velocity: { x: vx, y: vy },
            radius: size * (Math.random() * 0.6 + 0.7), color: color, rotation: 0, life: life, maxLife: life, alpha: 1, type: type
        });
    }
  };

  const spawnFloatingText = (pos: Vector2, text: string, color: string, scale: number = 1, duration: number = 0.8) => {
      floatingTextsRef.current.push({
          id: Math.random().toString(), position: { ...pos, y: pos.y - 10 }, velocity: { x: (Math.random() - 0.5) * 20, y: -50 },
          text, color, life: duration, maxLife: duration, scale
      });
  };

  const bankCoins = () => {
      const currentScore = scoreRef.current;
      const unbanked = currentScore - lastBankedScoreRef.current;
      if (unbanked >= 50) {
          const coins = Math.floor(unbanked / 50);
          propsRef.current.onAddCoins(coins);
          lastBankedScoreRef.current += coins * 50;
          spawnFloatingText(playerRef.current.position, `+${coins} COINS`, '#fbbf24', 2.0);
      }
  };

  const executeDash = () => {
      if (playerRef.current.dashCooldown <= 0) {
          playerRef.current.dashCooldown = ESCAPE_DASH_COOLDOWN;
          let dx = 0, dy = -1;
          const moveX = propsRef.current.moveInput?.x || 0;
          const moveY = propsRef.current.moveInput?.y || 0;
          if (Math.hypot(moveX, moveY) > 0.1) {
              const len = Math.hypot(moveX, moveY);
              dx = moveX / len; dy = moveY / len;
          } else {
               const velLen = Math.hypot(playerRef.current.velocity.x, playerRef.current.velocity.y);
               if (velLen > 10) { dx = playerRef.current.velocity.x / velLen; dy = playerRef.current.velocity.y / velLen; }
          }
          playerRef.current.dashActiveTimer = 0.25;
          playerRef.current.velocity.x = dx * ESCAPE_DASH_FORCE;
          playerRef.current.velocity.y = dy * ESCAPE_DASH_FORCE;
          spawnParticles(playerRef.current.position, 15, playerRef.current.color, 150, 0.5, 3);
          SoundManager.playUltDash();
      }
  };

  const executeShield = () => {
      if (playerRef.current.shieldCooldown <= 0) {
          playerRef.current.shieldCooldown = ESCAPE_SHIELD_COOLDOWN;
          playerRef.current.shieldActiveTimer = ESCAPE_SHIELD_DURATION;
          spawnFloatingText(playerRef.current.position, "SHIELD", "#3b82f6", 1.2);
          SoundManager.playUltShield();
      }
  };

  const changeShape = useCallback((newShape: ShapeType) => {
      if (newShape === playerRef.current.shape) return;
      if (waveRef.current === 0) {
          if (newShape === ShapeType.TRIANGLE) wave0FlagsRef.current.add('shifted_triangle');
          if (newShape === ShapeType.SQUARE) wave0FlagsRef.current.add('shifted_square');
      }
      const visualColor = getSkinThemeColor(skin, SHAPE_CONFIG[newShape].color);
      playerRef.current.previousShape = playerRef.current.shape;
      playerRef.current.shape = newShape;
      playerRef.current.isTransforming = true;
      playerRef.current.transformTime = 0;
      playerRef.current.color = visualColor;
      playerRef.current.transformDuration = TRANSFORM_DURATION;
      playerRef.current.ultActiveTimer = 0;
      playerRef.current.activeUltimateType = null;
      propsRef.current.onShapeChange(newShape);
      SoundManager.playTransform();
      spawnParticles(playerRef.current.position, 15, visualColor, 200, 0.5, 4);
  }, [skin, getSkinThemeColor]);

  const activateUltimate = useCallback(() => {
    if (propsRef.current.isPaused || propsRef.current.isGameOver) return;
    if (playerRef.current.ultimateCharge < 100) return;
    if (waveRef.current === 0) wave0FlagsRef.current.add('ult_used');
    playerRef.current.ultimateCharge = 0;
    const shape = playerRef.current.shape;
    const equipMap = propsRef.current.equipped?.ultimates || {};
    const selectedUlt = equipMap[shape] || DEFAULT_LOADOUT_ULTIMATES[shape];
    const config = ULTIMATE_CONFIG[selectedUlt];
    playerRef.current.activeUltimateType = selectedUlt;
    playerRef.current.ultActiveTimer = config.duration;
    propsRef.current.onUltChargeChange(0);
    const energyColor = getSkinThemeColor(skin, config.color);
    spawnFloatingText(playerRef.current.position, config.name, energyColor, 2.0);
    spawnParticles(playerRef.current.position, 40, energyColor, 300, 0.6, 3);
    if (shape === ShapeType.CIRCLE) SoundManager.playUltDash();
    else if (shape === ShapeType.SQUARE) SoundManager.playUltShield();
    else SoundManager.playUltBlade();
  }, [skin, getSkinThemeColor]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (propsRef.current.isPaused) return;
      keysPressed.current.add(e.key.toLowerCase());
      let newShape: ShapeType | null = null;
      if (KEYS.SHAPE_CIRCLE.includes(e.key)) newShape = ShapeType.CIRCLE;
      if (KEYS.SHAPE_SQUARE.includes(e.key)) newShape = ShapeType.SQUARE;
      if (KEYS.SHAPE_TRIANGLE.includes(e.key)) newShape = ShapeType.TRIANGLE;
      if (newShape) changeShape(newShape);
      if (e.code === 'Space') { e.preventDefault(); activateUltimate(); }
      if (gameMode === GameMode.ESCAPE) {
          if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') executeDash();
          if (e.code === 'KeyF') executeShield(); 
          if (e.code === 'KeyC') isSlowMoHeldRef.current = true;
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => {
        keysPressed.current.delete(e.key.toLowerCase());
        if (gameMode === GameMode.ESCAPE && e.code === 'KeyC') isSlowMoHeldRef.current = false;
    };
    const handleMouseMove = (e: MouseEvent) => {
        const isRotated = getFlippedState();
        if (isRotated) { const w = window.innerHeight; mousePos.current = { x: e.clientY, y: w - e.clientX }; }
        else { mousePos.current = { x: e.clientX, y: e.clientY }; }
        hasMovedMouse.current = true;
        if (waveRef.current === 0 && propsRef.current.showAimHintTrigger && !propsRef.current.playerHasAimed) {
            propsRef.current.onPlayerAimed?.();
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousemove', handleMouseMove);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousemove', handleMouseMove);
    };
  }, [activateUltimate, changeShape, gameMode]);

  const createEnemy = (type: EnemyType, x: number, y: number, wave: number, isBoss: boolean = false, isSafe: boolean = false): Enemy => {
    const config = ENEMY_TYPES_CONFIG[type];
    const diff = DIFFICULTY_CONFIG[difficulty || Difficulty.NORMAL];
    let health = (config.health + (wave * 1.2)) * diff.hpMult;
    let damage = (config.damage + (wave * 0.15)) * diff.dmgMult;
    let speed = (config.speed + (wave * 0.4)) * diff.speedMult;
    let attackCooldown = (config as any).attackCooldown || 2.0;
    if (isSafe) { health = 1; damage = 0; }
    return {
        id: Math.random().toString(), type, position: { x, y }, velocity: { x: 0, y: 0 }, 
        radius: config.radius * gameScale, color: config.color, rotation: 0,
        health, maxHealth: health, damage, speed, scoreValue: Math.floor(config.score * diff.scoreMult), 
        attackTimer: attackCooldown, attackCooldown: attackCooldown,
        hitFlash: 0, stunTimer: 0, isBoss, stunMeter: 0, maxStunMeter: 100
    };
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    let animationFrameId: number;
    let lastTime = performance.now();

    const drawShapeBody = (shape: ShapeType, size: number, alpha: number, color: string) => {
        ctx.save(); ctx.beginPath(); ctx.globalAlpha = alpha;
        if (shape === ShapeType.CIRCLE) ctx.arc(0, 0, size, 0, Math.PI * 2);
        else if (shape === ShapeType.SQUARE) ctx.rect(-size, -size, size * 2, size * 2);
        else if (shape === ShapeType.TRIANGLE) { ctx.moveTo(size * 1.2, 0); ctx.lineTo(-size, size); ctx.lineTo(-size, -size); ctx.closePath(); }
        ctx.fillStyle = color; ctx.fill(); ctx.strokeStyle = '#fff'; ctx.lineWidth = 2; ctx.stroke();
        ctx.restore();
    };

    const render = (now: number) => {
      const p = propsRef.current; 
      if (!p.gameStarted || p.isPaused || p.isGameOver) { lastTime = now; animationFrameId = requestAnimationFrame(render); return; }
      const dt = Math.min((now - lastTime) / 1000, 0.1); lastTime = now;
      const width = canvas.width / preset.dpr, height = canvas.height / preset.dpr;
      timeRef.current += dt;

      // Logic Updates (Movement, Spawning, Collision)
      const player = playerRef.current;
      let moveDir = { x: 0, y: 0 };
      if (KEYS.UP.some(k => keysPressed.current.has(k.toLowerCase()))) moveDir.y -= 1;
      if (KEYS.DOWN.some(k => keysPressed.current.has(k.toLowerCase()))) moveDir.y += 1;
      if (KEYS.LEFT.some(k => keysPressed.current.has(k.toLowerCase()))) moveDir.x -= 1;
      if (KEYS.RIGHT.some(k => keysPressed.current.has(k.toLowerCase()))) moveDir.x += 1;
      moveDir = normalize(moveDir);
      player.position.x += moveDir.x * SHAPE_CONFIG[player.shape].speed * dt;
      player.position.y += moveDir.y * SHAPE_CONFIG[player.shape].speed * dt;
      player.position.x = clamp(player.position.x, player.radius, width - player.radius);
      player.position.y = clamp(player.position.y, player.radius, height - player.radius);

      // Rendering
      ctx.save(); ctx.scale(preset.dpr, preset.dpr); ctx.clearRect(0, 0, width, height);
      ctx.fillStyle = themeColors.bg; ctx.fillRect(0, 0, width, height);

      // HUD / Tutorial Help
      if (waveRef.current === 0) {
          ctx.fillStyle = "white"; ctx.textAlign = "center"; ctx.font = "bold 24px sans-serif";
          ctx.fillText("USE Q, E, R TO SHIFT SHAPES", width/2, height - 100);
      }

      drawShapeBody(player.shape, player.radius, 1, player.color);
      ctx.restore();
      animationFrameId = requestAnimationFrame(render);
    };
    render(performance.now());
    return () => cancelAnimationFrame(animationFrameId);
  }, [graphics, theme]);

  return <canvas ref={canvasRef} className="block w-full h-full" style={{ touchAction: 'none' }} />;
};

export default GameCanvas;

import React, { useEffect, useState, useRef } from 'react';
import { ShapeType, ItemType, UltimateType, GameMode, Mission, GameSettings } from '../types';
import { SHAPE_CONFIG, ITEM_CONFIG, ESCAPE_DASH_COOLDOWN, ESCAPE_SHIELD_COOLDOWN, ESCAPE_SLOWMO_MAX_CHARGE, ULTIMATE_CONFIG, ESCAPE_SHIELD_DURATION } from '../constants';
import { Circle, Square, Triangle, Heart, Zap, Wind, Hourglass, Sword, Pause, Play, Snail, Coins, Shield, RotateCcw, LogOut, Timer, Target as Crosshair } from 'lucide-react';
import { SoundManager } from '../audio';

interface HUDProps {
  health: number;
  maxHealth: number;
  score: number;
  wave: number;
  currentShape: ShapeType;
  activeBuffs: { type: ItemType; time: number }[];
  ultCharge: number;
  bossHealth: { current: number; max: number; name: string | null };
  isPaused: boolean;
  onTogglePause: () => void;
  isSlowMo: boolean;
  onToggleSlowMo: () => void;
  onActivateUltimate: () => void;
  onRestart: () => void;
  onQuit: () => void;
  unlockedShapes?: ShapeType[];
  coins?: number;
  onOpenShop?: () => void;
  onOpenUpgrades?: () => void;
  onOpenSettings: () => void; 
  onOpenManual: () => void; 
  onShapeSelect: (shape: ShapeType) => void;
  equippedUltimate?: UltimateType;
  highlightShapes?: boolean;
  tutorialHighlight?: ShapeType | null; 
  highlightUlt?: boolean; 
  onSkipTutorial?: () => void;
  canSkipTutorial?: boolean;
  gameMode?: GameMode;
  escapeTimer?: number;
  escapeState?: { dashCooldown: number, shieldCooldown: number, slowMoCharge: number };
  activeMission?: Mission;
  themeAnomaly?: boolean;
  onThemeAnomalyClick?: () => void;
  autoFirePC?: boolean;
  onToggleAutoFirePC?: () => void;
  isTouchDevice?: boolean;
  settings?: GameSettings;
}

const HUD: React.FC<HUDProps> = ({
  health,
  maxHealth,
  score,
  wave,
  currentShape,
  activeBuffs,
  ultCharge,
  bossHealth,
  isPaused,
  onTogglePause,
  isSlowMo,
  onToggleSlowMo,
  onActivateUltimate,
  onRestart,
  onQuit,
  unlockedShapes = [ShapeType.CIRCLE, ShapeType.SQUARE, ShapeType.TRIANGLE],
  coins = 0,
  onOpenShop,
  onShapeSelect,
  tutorialHighlight,
  highlightUlt = false,
  gameMode,
  escapeTimer,
  escapeState,
  autoFirePC,
  onToggleAutoFirePC,
  isTouchDevice = false,
  settings
}) => {
  const [hudScale, setHudScale] = useState(1);
  const isMinimal = settings?.minimalAndroidHUD;
  const shouldHideDetails = settings?.hideHudDetails;

  useEffect(() => {
    const updateScale = () => {
      const width = window.innerWidth;
      const baseScale = Math.max(0.8, width / 1400); 
      setHudScale(Math.min(baseScale, isTouchDevice ? 1.2 : 1.05));
    };
    updateScale();
    window.addEventListener('resize', updateScale);
    return () => window.removeEventListener('resize', updateScale);
  }, [isTouchDevice]);

  const healthPercentage = Math.max(0, (health / maxHealth) * 100);
  const getShapeIcon = (shape: ShapeType) => {
      const iconSize = "w-8 h-8 md:w-9 md:h-9"; 
      switch(shape) {
          case ShapeType.CIRCLE: return <Circle className={`text-white ${iconSize}`} />;
          case ShapeType.SQUARE: return <Square className={`text-white ${iconSize}`} />;
          case ShapeType.TRIANGLE: return <Triangle className={`text-white ${iconSize} mt-0.5 md:mt-1`} />;
      }
  };

  const getShapeName = (shape: ShapeType) => {
      switch(shape) {
          case ShapeType.CIRCLE: return "SPEED";
          case ShapeType.SQUARE: return "GUARD";
          case ShapeType.TRIANGLE: return "ATTACK";
      }
  };

  const getShapeKey = (shape: ShapeType) => {
    switch(shape) {
        case ShapeType.CIRCLE: return "Q";
        case ShapeType.SQUARE: return "E";
        case ShapeType.TRIANGLE: return "R";
    }
  };

  const getShapeClass = (shape: ShapeType) => {
    const isActive = currentShape === shape;
    const isHighlighted = tutorialHighlight === shape;
    const padding = "p-3 md:p-3.5"; 
    const minWidth = "min-w-[80px] md:min-w-[95px]"; 
    const base = `flex flex-col items-center justify-center ${padding} rounded-2xl transition-all duration-300 outline-none touch-manipulation relative overflow-hidden ${minWidth}`;
    let stateClass = isActive 
        ? `border-2 border-white/40 bg-white/10 scale-105 shadow-[0_0_20px_rgba(255,255,255,0.15)] backdrop-blur-md z-10` 
        : isHighlighted 
            ? `border-4 border-yellow-400 bg-yellow-500/20 scale-110 shadow-[0_0_30px_rgba(234,179,8,0.6)] animate-pulse z-20 opacity-100`
            : "border border-transparent opacity-60 scale-100 active:scale-95 hover:bg-slate-800/40";
    return `${base} ${stateClass}`;
  };

  const [displayHealth, setDisplayHealth] = useState(health);
  useEffect(() => {
    let animationFrame: number;
    let last = performance.now();
    const animate = (now: number) => {
        const dt = (now - last) / 1000;
        last = now;
        setDisplayHealth(prev => {
            const diff = health - prev;
            if (Math.abs(diff) < 0.1) return health;
            return prev + diff * (1 - Math.exp(-6 * dt));
        });
        animationFrame = requestAnimationFrame(animate);
    };
    animationFrame = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(animationFrame);
  }, [health]);

  const displayHealthPercent = (displayHealth / maxHealth) * 100;
  const showTopBar = wave > 0 || tutorialHighlight !== undefined || highlightUlt; 
  const utilityBtnSize = "p-2.5 md:p-3";
  const utilityIconSize = "w-5 h-5 md:w-6 md:h-6";

  const renderSkillBars = () => {
      if (shouldHideDetails) return null;
      const bars = [];
      if (gameMode === GameMode.ESCAPE && escapeState) {
          const dashPct = Math.max(0, 100 - (escapeState.dashCooldown / ESCAPE_DASH_COOLDOWN) * 100);
          bars.push(
              <div key="dash" className="flex items-center gap-2 group">
                  <Wind size={12} className={`shrink-0 ${dashPct < 100 ? 'text-slate-500' : 'text-cyan-400 animate-pulse'}`} />
                  <div className="flex-1 h-1 bg-slate-900/60 rounded-full border border-slate-800 overflow-hidden"><div className={`h-full ${dashPct < 100 ? 'bg-cyan-900/60' : 'bg-cyan-500'}`} style={{ width: `${dashPct}%` }} /></div>
                  {!isTouchDevice && <span className="text-[7px] font-black text-slate-500 w-6">SHIFT</span>}
              </div>
          );
      }
      return bars.length > 0 ? <div className="flex flex-col gap-1.5 mt-2.5 w-32 md:w-48">{bars}</div> : null;
  };

  return (
    <div className="absolute inset-0 pointer-events-none z-50 flex flex-col justify-between select-none" style={{ paddingTop: 'calc(0.75rem + var(--safe-top))', paddingLeft: 'calc(1rem + var(--safe-left))', paddingRight: 'calc(1rem + var(--safe-right))', paddingBottom: 'calc(0.75rem + var(--safe-bottom))' }}>
      {isPaused && (
         <div className="absolute inset-0 z-[60] flex items-center justify-center bg-slate-950/90 backdrop-blur-xl pointer-events-auto animate-in fade-in duration-200">
             <div className="bg-slate-900 border border-slate-700 p-8 rounded-2xl shadow-2xl flex flex-col gap-3 min-w-[300px] max-w-sm w-full animate-in zoom-in-95 duration-200" style={{ transform: `scale(${hudScale})` }}>
                 <h2 className="text-2xl font-black text-white text-center mb-4 tracking-widest uppercase">Paused</h2>
                 <button onClick={onTogglePause} className="flex items-center justify-center gap-3 w-full py-3.5 bg-white text-slate-900 font-bold rounded-xl hover:bg-slate-200 transition-all">
                    <Play size={22} fill="currentColor" /> RESUME
                 </button>
                 <button onClick={onRestart} className="flex items-center justify-center gap-3 w-full py-3.5 bg-slate-800 text-slate-200 font-bold rounded-xl border border-slate-700 hover:bg-slate-700 transition-all">
                     <RotateCcw size={18} /> RESTART
                 </button>
                 <button onClick={onQuit} className="flex items-center justify-center gap-3 w-full py-3.5 bg-red-900/20 text-red-400 font-bold rounded-xl border border-red-900/30 hover:bg-red-900/40 transition-all mt-2">
                     <LogOut size={18} /> QUIT
                 </button>
             </div>
         </div>
      )}
      <div className={`flex justify-between items-start pointer-events-auto transition-opacity duration-1000 ${showTopBar ? 'opacity-100' : 'opacity-0'}`}>
        <div className="flex flex-col" style={{ transform: `scale(${hudScale})`, transformOrigin: 'top left' }}>
           <div className="flex flex-col w-44 md:w-64 gap-1.5">
                <div className="flex items-center gap-2 text-white font-black text-lg"><Heart className="w-6 h-6" /><span>{Math.ceil(health)}</span></div>
                <div className="w-full h-5 bg-slate-900/80 rounded-full overflow-hidden border-2 border-slate-700 relative shadow-lg">
                    <div className="absolute top-0 left-0 h-full bg-white opacity-20" style={{ width: `${displayHealthPercent}%` }} />
                    <div className="absolute top-0 left-0 h-full bg-rose-500" style={{ width: `${healthPercentage}%` }} />
                </div>
           </div>
           {renderSkillBars()}
        </div>
        <div className="text-right flex flex-col items-end gap-1" style={{ transform: `scale(${hudScale})`, transformOrigin: 'top right' }}>
          <div className="flex gap-2.5 mb-1">
               {!isTouchDevice && onToggleAutoFirePC && (
                   <button onClick={onToggleAutoFirePC} className={`${utilityBtnSize} rounded-xl border-2 ${autoFirePC ? 'bg-cyan-600 border-cyan-400 text-white' : 'bg-slate-800 border-slate-600 text-slate-400'}`}><Crosshair className={utilityIconSize} /></button>
               )}
               <button onClick={onTogglePause} className={`${utilityBtnSize} rounded-xl border-2 bg-slate-800 border-slate-600 text-slate-400`}>{isPaused ? <Play className={utilityIconSize} /> : <Pause className={utilityIconSize} />}</button>
          </div>
          <div className="flex items-center gap-1 text-amber-400 font-bold text-lg mb-0.5"><span>{coins.toLocaleString()}</span><Coins className="w-4 h-4" /></div>
          <div className="text-4xl font-black text-white drop-shadow-lg tracking-tighter">{score.toLocaleString()}</div>
          <div className="text-cyan-400 font-bold text-lg tracking-widest uppercase">{gameMode === GameMode.TOWER ? `Floor ${wave}` : `Wave ${wave}`}</div>
        </div>
      </div>
      <div className="fixed bottom-6 left-1/2 flex flex-col items-center pointer-events-none z-[50]" style={{ transform: `translateX(-50%) scale(${hudScale})`, transformOrigin: 'bottom center' }}>
         {!isPaused && (
             <div className="flex justify-center items-end gap-4">
                {unlockedShapes.map(shape => (
                     <div key={shape} className="flex flex-col items-center">
                        <button onPointerDown={(e) => { e.stopPropagation(); onShapeSelect(shape); }} className={`pointer-events-auto ${getShapeClass(shape)}`}>
                            <div className={`${SHAPE_CONFIG[shape].uiColor} p-4 rounded-xl mb-1.5 shadow-lg`}>{getShapeIcon(shape)}</div>
                            <span className={`text-xs font-black ${currentShape === shape ? 'text-white' : 'text-slate-400'}`}>{getShapeName(shape)}</span>
                        </button>
                        {!isTouchDevice && <div className="text-[10px] font-black font-mono text-slate-600 mt-1 uppercase">[{getShapeKey(shape)}]</div>}
                     </div>
                ))}
             </div>
         )}
      </div>
    </div>
  );
};

export default HUD;

