const ESCAPE_WAVE_DURATION = 30;

const GameCanvas: React.FC<GameCanvasProps> = (props) => {
  const { isGameOver, isPaused, gameStarted, isSlowMo, ultTrigger, restartTrigger, equipped, upgrades, moveInput, aimInput, requestedShape, onShapeRequestProcessed, wave, difficulty = Difficulty.NORMAL, gameMode = GameMode.SURVIVAL, triggerDash, triggerShield, isSlowMoHeld, graphics, playerHasMoved, playerHasAimed, showAimHintTrigger, autoFirePC = true, isTouchDevice = false } = props;
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const propsRef = useRef(props);
  propsRef.current = props;

  const theme = equipped?.theme || ThemeType.DEFAULT;
  const skin = equipped?.skin || SkinType.DEFAULT;
  const themeColors = THEME_COLORS[theme] || THEME_COLORS.DEFAULT;

  const bgParticlesRef = useRef<BgParticle[]>([]);
  const lastThemeRef = useRef<ThemeType>(theme);
  const preset = GRAPHICS_PRESETS[graphics] || GRAPHICS_PRESETS.MEDIUM;

  const isMobile = window.innerWidth < 768;
  const gameScale = isMobile ? 0.8 : 1.0;

  const playerRef = useRef<Player>({
    id: 'player',
    position: { x: 0, y: 0 },
    velocity: { x: 0, y: 0 },
    radius: PLAYER_RADIUS * gameScale,
    color: SHAPE_CONFIG[ShapeType.CIRCLE].color,
    rotation: 0,
    shape: ShapeType.CIRCLE,
    health: PLAYER_MAX_HEALTH,
    maxHealth: PLAYER_MAX_HEALTH,
    cooldown: 0,
    iframe: 0,
    hitFlash: 0,
    previousShape: null,
    isTransforming: false,
    transformTime: 0,
    transformDuration: TRANSFORM_DURATION,
    effectSpeed: 0,
    effectPower: 0,
    effectSlow: 0,
    ultimateCharge: 0,
    ultActiveTimer: 0,
    activeUltimateType: null,
    webbedTimer: 0,
    stunnedTimer: 0,
    defenseBreakTimer: 0,
    parryWindowTimer: 0,
    dodgeCounter: 0,
    dodgeResetTimer: 0,
    ghostTimer: 0,
    skinTimer: 0,
    themeTimer: 0,
    killsSinceHeal: 0,
    clone1Pos: { x:0, y:0 },
    clone2Pos: { x:0, y:0 },
    dashCooldown: 0,
    shieldActiveTimer: 0,
    shieldCooldown: 0,
    slowMoCharge: ESCAPE_SLOWMO_MAX_CHARGE,
    dashActiveTimer: 0
  });

  const enemiesRef = useRef<Enemy[]>([]);
  const projectilesRef = useRef<Projectile[]>([]);
  const particlesRef = useRef<Particle[]>([]);
  const itemsRef = useRef<Item[]>([]);
  const floatingTextsRef = useRef<FloatingText[]>([]);

  const scoreRef = useRef(0);
  const lastBankedScoreRef = useRef(0);
  const waveRef = useRef(0);
  const timeRef = useRef(0);
  const lastSpawnRef = useRef(0);
  const waveDelayTimerRef = useRef(WAVE_DELAY_DURATION);
  const bossSpawnedRef = useRef(false);
  const enemiesSpawnedCountRef = useRef(0);

  const killStreakRef = useRef(0);
  const lastKillTimeRef = useRef(0);

  const towerTransitionRef = useRef<{active: boolean, timer: number, phase: 'OUT'|'IN', nextFloor: number}>({
    active: false, timer: 0, phase: 'OUT', nextFloor: 1
  });

  const isDyingRef = useRef(false);
  const deathTimerRef = useRef(0);
  const escapeWaveTimerRef = useRef(ESCAPE_WAVE_DURATION);
  const wave0TimerRef = useRef(0);
  const wave0FlagsRef = useRef<Set<string>>(new Set());
  const lastTutorialModeRef = useRef(false);
  const smartHintsRef = useRef({ block: false, damage: false, speed: false });
  const lastUiUpdateRef = useRef(0);
  const UI_UPDATE_INTERVAL = 0.1; 

  const timeScaleRef = useRef(1.0);
  const targetTimeScaleRef = useRef(1.0);
  const slowmoActiveRef = useRef(false);
  const slowmoTimerRef = useRef(0);
  const slowmoCooldownTimerRef = useRef(0);

  const screenShakeRef = useRef(0);
  const keysPressed = useRef<Set<string>>(new Set());
  const mousePos = useRef<Vector2>({ x: 0, y: 0 });
  const isMouseDown = useRef(false);
  const hasMovedMouse = useRef(false);
  const isMouseDeviceRef = useRef(false);
  const isSlowMoHeldRef = useRef(false);

  const tutorialAlphaRef = useRef(1.0);
  const aimTutorialAlphaRef = useRef(0);

  const getFlippedState = () => {
      return window.innerHeight > window.innerWidth && window.innerWidth <= 1024;
  };

  const getSkinThemeColor = useCallback((currentSkin: SkinType, shapeColor: string) => {
    switch(currentSkin) {
      case SkinType.NEON: return '#ffffff';
      case SkinType.METALLIC: return '#e2e8f0';
      case SkinType.SHADOW: return '#a855f7';
      case SkinType.PRISM: return `hsl(${(timeRef.current * 100) % 360}, 70%, 60%)`;
      case SkinType.CYBER: return '#22d3ee';
      case SkinType.LAVA: return '#ef4444';
      case SkinType.ICE: return '#bae6fd';
      case SkinType.PIXEL: return '#4ade80';
      case SkinType.GOLD: return '#fbbf24';
      case SkinType.COSMIC: return '#f8fafc';
      case SkinType.HOLOGRAM: return shapeColor;
      default: return shapeColor;
    }
  }, []);

  useEffect(() => {
    if (props.isGameOver) return;
    if (waveRef.current === 0 && wave === 1) {
        enemiesRef.current = [];
        projectilesRef.current = [];
        waveDelayTimerRef.current = 2.0;
        wave0TimerRef.current = 0;
        wave0FlagsRef.current.clear();
        if (props.onTutorialMode) props.onTutorialMode(false);
    }
    waveRef.current = wave;
  }, [wave, props.isGameOver, props.onTutorialMode]);

  const resetGame = useCallback(() => {
    const isRotated = getFlippedState();
    const width = isRotated ? window.innerHeight : window.innerWidth;
    const height = isRotated ? window.innerWidth : window.innerHeight;

    if (width === 0 || height === 0) return;

    let maxHealth = PLAYER_MAX_HEALTH;
    if (upgrades) {
        const circleHP = (upgrades[ShapeType.CIRCLE]?.STAT_4 || 0) * UPGRADE_TREE[ShapeType.CIRCLE].STAT_4.increment;
        const squareHP = (upgrades[ShapeType.SQUARE]?.STAT_4 || 0) * UPGRADE_TREE[ShapeType.SQUARE].STAT_4.increment;
        const triangleHP = (upgrades[ShapeType.TRIANGLE]?.STAT_4 || 0) * UPGRADE_TREE[ShapeType.TRIANGLE].STAT_4.increment;
        maxHealth += circleHP + squareHP + triangleHP;
    }

    const startWave = propsRef.current.wave;
    const initialShape = ShapeType.CIRCLE;
    const initialColor = getSkinThemeColor(skin, SHAPE_CONFIG[initialShape].color);

    playerRef.current = {
      ...playerRef.current,
      position: { x: width / 2, y: height / 2 },
      health: maxHealth,
      maxHealth: maxHealth,
      shape: initialShape,
      velocity: { x: 0, y: 0 },
      cooldown: 0,
      iframe: 0,
      hitFlash: 0,
      previousShape: null,
      isTransforming: false,
      transformTime: 0,
      transformDuration: TRANSFORM_DURATION,
      effectSpeed: 0,
      effectPower: 0,
      effectSlow: 0,
      ultimateCharge: 0,
      ultActiveTimer: 0,
      activeUltimateType: null,
      webbedTimer: 0,
      stunnedTimer: 0,
      defenseBreakTimer: 0,
      parryWindowTimer: 0,
      dodgeCounter: 0,
      dodgeResetTimer: 0,
      ghostTimer: 0,
      skinTimer: 0,
      themeTimer: 0,
      killsSinceHeal: 0,
      clone1Pos: { x: width/2, y: height/2 },
      clone2Pos: { x: width/2, y: height/2 },
      color: initialColor,
      radius: PLAYER_RADIUS * gameScale,
      dashCooldown: 0,
      shieldActiveTimer: 0,
      shieldCooldown: 0,
      slowMoCharge: ESCAPE_SLOWMO_MAX_CHARGE,
      dashActiveTimer: 0
    };
    enemiesRef.current = [];
    projectilesRef.current = [];
    particlesRef.current = [];
    itemsRef.current = [];
    floatingTextsRef.current = [];
    scoreRef.current = 0;
    lastBankedScoreRef.current = 0;
    waveRef.current = startWave;
    timeRef.current = 0;
    lastSpawnRef.current = 0;
    lastUiUpdateRef.current = 0;
    screenShakeRef.current = 0;
    waveDelayTimerRef.current = startWave === 0 ? 0 : 2.0; 
    escapeWaveTimerRef.current = ESCAPE_WAVE_DURATION;
    towerTransitionRef.current = { active: false, timer: 0, phase: 'OUT', nextFloor: 1 };
    isDyingRef.current = false;
    deathTimerRef.current = 0;
    bossSpawnedRef.current = false;
    enemiesSpawnedCountRef.current = 0;
    wave0TimerRef.current = 0;
    wave0FlagsRef.current.clear();
    lastTutorialModeRef.current = false;
    if (propsRef.current.onTutorialMode) propsRef.current.onTutorialMode(false);
    if (propsRef.current.onTutorialHighlight) propsRef.current.onTutorialHighlight(null);
    if (propsRef.current.onTutorialUltHighlight) propsRef.current.onTutorialUltHighlight(false);
    smartHintsRef.current = { block: false, damage: false, speed: false };
    bgParticlesRef.current = [];
    timeScaleRef.current = 1.0;
    targetTimeScaleRef.current = 1.0;
    slowmoActiveRef.current = false;
    slowmoTimerRef.current = 0;
    slowmoCooldownTimerRef.current = 0;
    tutorialAlphaRef.current = 1.0;
    aimTutorialAlphaRef.current = 0;
    killStreakRef.current = 0;
    lastKillTimeRef.current = 0;

    const p = propsRef.current;
    p.onHealthChange(maxHealth, maxHealth);
    p.onScoreChange(0);
    p.onWaveChange(startWave);
    p.onBuffsChange([]);
    p.onShapeChange(initialShape);
    p.onUltChargeChange(0);
    p.onBossHealthChange(0, 100, null);

    if (propsRef.current.gameStarted) {
        SoundManager.startMusic();
        SoundManager.setMusicIntensity(0);
    }
  }, [upgrades, gameScale, skin, getSkinThemeColor]);

  useEffect(() => {
      if (restartTrigger > 0) {
          resetGame();
      }
  }, [restartTrigger, resetGame]);

  useEffect(() => {
    isMouseDeviceRef.current = window.matchMedia('(pointer: fine)').matches && !isTouchDevice;
    const handleResize = () => {
        if (canvasRef.current) {
            const dpr = preset.dpr;
            const isRotated = getFlippedState();
            const w = isRotated ? window.innerHeight : window.innerWidth;
            const h = isRotated ? window.innerWidth : window.innerHeight;
            canvasRef.current.width = w * dpr;
            canvasRef.current.height = h * dpr;
        }
    };
    if (!propsRef.current.isGameOver) {
      handleResize();
      if (restartTrigger === 0 && waveRef.current === 0 && enemiesRef.current.length === 0 && wave0TimerRef.current === 0) {
          resetGame();
      }
    } else {
        SoundManager.stopMusic();
    }
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [propsRef.current.isGameOver, resetGame, graphics, isTouchDevice, preset.dpr]);

  const spawnParticles = (pos: Vector2, count: number, color: string, speed: number, life: number = 0.6, size: number = 2, type: string = 'NORMAL') => {
    const limit = preset.maxParticles;
    let themeMultiplier = (theme === ThemeType.LAVA || theme === ThemeType.STORM || theme === ThemeType.CRYSTAL || theme === ThemeType.CYBER || theme === ThemeType.HACKER) ? 0.35 : 1.0;
    const requestedCount = Math.ceil(count * themeMultiplier);
    if (particlesRef.current.length + requestedCount > limit) {
        if (particlesRef.current.length > limit) particlesRef.current.splice(0, requestedCount);
        count = Math.min(requestedCount, Math.max(0, limit - particlesRef.current.length + 10));
    } else {
        count = requestedCount;
    }
    for (let i = 0; i < count; i++) {
        const angle = Math.random() * Math.PI * 2;
        const v = (Math.random() * 0.5 + 0.5) * speed;
        let vx = Math.cos(angle) * v;
        let vy = Math.sin(angle) * v;
        if (type === 'PICKUP_SPARK') { vx = (Math.random() - 0.5) * speed * 0.5; vy = -Math.random() * speed; }
        particlesRef.current.push({
            id: 'p', position: { x: pos.x, y: pos.y }, velocity: { x: vx, y: vy },
            radius: size * (Math.random() * 0.6 + 0.7), color: color, rotation: 0, life: life, maxLife: life, alpha: 1, type: type
        });
    }
  };

  const spawnFloatingText = (pos: Vector2, text: string, color: string, scale: number = 1, duration: number = 0.8) => {
      floatingTextsRef.current.push({
          id: Math.random().toString(), position: { ...pos, y: pos.y - 10 }, velocity: { x: (Math.random() - 0.5) * 20, y: -50 },
          text, color, life: duration, maxLife: duration, scale
      });
  };

  const bankCoins = () => {
      const currentScore = scoreRef.current;
      const unbanked = currentScore - lastBankedScoreRef.current;
      if (unbanked >= 50) {
          const coins = Math.floor(unbanked / 50);
          propsRef.current.onAddCoins(coins);
          lastBankedScoreRef.current += coins * 50;
          spawnFloatingText(playerRef.current.position, `+${coins} COINS`, '#fbbf24', 2.0);
      }
  };

  const executeDash = () => {
      if (playerRef.current.dashCooldown <= 0) {
          playerRef.current.dashCooldown = ESCAPE_DASH_COOLDOWN;
          let dx = 0, dy = -1;
          const moveX = propsRef.current.moveInput?.x || 0;
          const moveY = propsRef.current.moveInput?.y || 0;
          if (Math.hypot(moveX, moveY) > 0.1) {
              const len = Math.hypot(moveX, moveY);
              dx = moveX / len; dy = moveY / len;
          } else {
               const velLen = Math.hypot(playerRef.current.velocity.x, playerRef.current.velocity.y);
               if (velLen > 10) { dx = playerRef.current.velocity.x / velLen; dy = playerRef.current.velocity.y / velLen; }
          }
          playerRef.current.dashActiveTimer = 0.25;
          playerRef.current.velocity.x = dx * ESCAPE_DASH_FORCE;
          playerRef.current.velocity.y = dy * ESCAPE_DASH_FORCE;
          spawnParticles(playerRef.current.position, 15, playerRef.current.color, 150, 0.5, 3);
          SoundManager.playUltDash();
      }
  };

  const executeShield = () => {
      if (playerRef.current.shieldCooldown <= 0) {
          playerRef.current.shieldCooldown = ESCAPE_SHIELD_COOLDOWN;
          playerRef.current.shieldActiveTimer = ESCAPE_SHIELD_DURATION;
          spawnFloatingText(playerRef.current.position, "SHIELD", "#3b82f6", 1.2);
          SoundManager.playUltShield();
      }
  };

  const changeShape = useCallback((newShape: ShapeType) => {
      if (newShape === playerRef.current.shape) return;
      if (waveRef.current === 0) {
          if (newShape === ShapeType.TRIANGLE) wave0FlagsRef.current.add('shifted_triangle');
          if (newShape === ShapeType.SQUARE) wave0FlagsRef.current.add('shifted_square');
      }
      const visualColor = getSkinThemeColor(skin, SHAPE_CONFIG[newShape].color);
      playerRef.current.previousShape = playerRef.current.shape;
      playerRef.current.shape = newShape;
      playerRef.current.isTransforming = true;
      playerRef.current.transformTime = 0;
      playerRef.current.color = visualColor;
      playerRef.current.transformDuration = TRANSFORM_DURATION;
      playerRef.current.ultActiveTimer = 0;
      playerRef.current.activeUltimateType = null;
      propsRef.current.onShapeChange(newShape);
      SoundManager.playTransform();
      spawnParticles(playerRef.current.position, 15, visualColor, 200, 0.5, 4);
  }, [skin, getSkinThemeColor]);

  const activateUltimate = useCallback(() => {
    if (propsRef.current.isPaused || propsRef.current.isGameOver) return;
    if (playerRef.current.ultimateCharge < 100) return;
    if (waveRef.current === 0) wave0FlagsRef.current.add('ult_used');
    playerRef.current.ultimateCharge = 0;
    const shape = playerRef.current.shape;
    const equipMap = propsRef.current.equipped?.ultimates || {};
    // Fixed: DEFAULT_LOADOUT_ULTIMATES is now correctly imported from constants
    const selectedUlt = equipMap[shape] || DEFAULT_LOADOUT_ULTIMATES[shape];
    const config = ULTIMATE_CONFIG[selectedUlt];
    playerRef.current.activeUltimateType = selectedUlt;
    playerRef.current.ultActiveTimer = config.duration;
    propsRef.current.onUltChargeChange(0);
    const energyColor = getSkinThemeColor(skin, config.color);
    spawnFloatingText(playerRef.current.position, config.name, energyColor, 2.0);
    spawnParticles(playerRef.current.position, 40, energyColor, 300, 0.6, 3);
    if (shape === ShapeType.CIRCLE) SoundManager.playUltDash();
    else if (shape === ShapeType.SQUARE) SoundManager.playUltShield();
    else SoundManager.playUltBlade();
  }, [skin, getSkinThemeColor]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (propsRef.current.isPaused) return;
      keysPressed.current.add(e.key.toLowerCase());
      let newShape: ShapeType | null = null;
      if (KEYS.SHAPE_CIRCLE.includes(e.key)) newShape = ShapeType.CIRCLE;
      if (KEYS.SHAPE_SQUARE.includes(e.key)) newShape = ShapeType.SQUARE;
      if (KEYS.SHAPE_TRIANGLE.includes(e.key)) newShape = ShapeType.TRIANGLE;
      if (newShape) changeShape(newShape);
      if (e.code === 'Space') { e.preventDefault(); activateUltimate(); }
      if (gameMode === GameMode.ESCAPE) {
          if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') executeDash();
          if (e.code === 'KeyF') executeShield(); 
          if (e.code === 'KeyC') isSlowMoHeldRef.current = true;
      }
    };
    const handleKeyUp = (e: KeyboardEvent) => {
        keysPressed.current.delete(e.key.toLowerCase());
        if (gameMode === GameMode.ESCAPE && e.code === 'KeyC') isSlowMoHeldRef.current = false;
    };
    const handleMouseMove = (e: MouseEvent) => {
        const isRotated = getFlippedState();
        if (isRotated) { const w = window.innerHeight; mousePos.current = { x: e.clientY, y: w - e.clientX }; }
        else { mousePos.current = { x: e.clientX, y: e.clientY }; }
        hasMovedMouse.current = true;
        if (waveRef.current === 0 && propsRef.current.showAimHintTrigger && !propsRef.current.playerHasAimed) {
            propsRef.current.onPlayerAimed?.();
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousemove', handleMouseMove);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('mousemove', handleMouseMove);
    };
  }, [activateUltimate, changeShape, gameMode]);

  const createEnemy = (type: EnemyType, x: number, y: number, wave: number, isBoss: boolean = false, isSafe: boolean = false): Enemy => {
    const config = ENEMY_TYPES_CONFIG[type];
    const diff = DIFFICULTY_CONFIG[difficulty || Difficulty.NORMAL];
    let health = (config.health + (wave * 1.2)) * diff.hpMult;
    let damage = (config.damage + (wave * 0.15)) * diff.dmgMult;
    let speed = (config.speed + (wave * 0.4)) * diff.speedMult;
    let attackCooldown = (config as any).attackCooldown || 2.0;
    if (isSafe) { health = 1; damage = 0; }
    return {
        id: Math.random().toString(), type, position: { x, y }, velocity: { x: 0, y: 0 }, 
        radius: config.radius * gameScale, color: config.color, rotation: 0,
        health, maxHealth: health, damage, speed, scoreValue: Math.floor(config.score * diff.scoreMult), 
        attackTimer: attackCooldown, attackCooldown: attackCooldown,
        hitFlash: 0, stunTimer: 0, isBoss, stunMeter: 0, maxStunMeter: 100
    };
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    let animationFrameId: number;
    let lastTime = performance.now();

    const drawShapeBody = (shape: ShapeType, size: number, alpha: number, color: string) => {
        ctx.save(); ctx.beginPath(); ctx.globalAlpha = alpha;
        if (shape === ShapeType.CIRCLE) ctx.arc(0, 0, size, 0, Math.PI * 2);
        else if (shape === ShapeType.SQUARE) ctx.rect(-size, -size, size * 2, size * 2);
        else if (shape === ShapeType.TRIANGLE) { ctx.moveTo(size * 1.2, 0); ctx.lineTo(-size, size); ctx.lineTo(-size, -size); ctx.closePath(); }
        ctx.fillStyle = color; ctx.fill(); ctx.strokeStyle = '#fff'; ctx.lineWidth = 2; ctx.stroke();
        ctx.restore();
    };

    const render = (now: number) => {
      const p = propsRef.current; 
      if (!p.gameStarted || p.isPaused || p.isGameOver) { lastTime = now; animationFrameId = requestAnimationFrame(render); return; }
      const dt = Math.min((now - lastTime) / 1000, 0.1); lastTime = now;
      const width = canvas.width / preset.dpr, height = canvas.height / preset.dpr;
      timeRef.current += dt;

      // Logic Updates (Movement, Spawning, Collision)
      const player = playerRef.current;
      let moveDir = { x: 0, y: 0 };
      if (KEYS.UP.some(k => keysPressed.current.has(k.toLowerCase()))) moveDir.y -= 1;
      if (KEYS.DOWN.some(k => keysPressed.current.has(k.toLowerCase()))) moveDir.y += 1;
      if (KEYS.LEFT.some(k => keysPressed.current.has(k.toLowerCase()))) moveDir.x -= 1;
      if (KEYS.RIGHT.some(k => keysPressed.current.has(k.toLowerCase()))) moveDir.x += 1;
      moveDir = normalize(moveDir);
      player.position.x += moveDir.x * SHAPE_CONFIG[player.shape].speed * dt;
      player.position.y += moveDir.y * SHAPE_CONFIG[player.shape].speed * dt;
      player.position.x = clamp(player.position.x, player.radius, width - player.radius);
      player.position.y = clamp(player.position.y, player.radius, height - player.radius);

      // Rendering
      ctx.save(); ctx.scale(preset.dpr, preset.dpr); ctx.clearRect(0, 0, width, height);
      ctx.fillStyle = themeColors.bg; ctx.fillRect(0, 0, width, height);

      // HUD / Tutorial Help
      if (waveRef.current === 0) {
          ctx.fillStyle = "white"; ctx.textAlign = "center"; ctx.font = "bold 24px sans-serif";
          ctx.fillText("USE Q, E, R TO SHIFT SHAPES", width/2, height - 100);
      }

      drawShapeBody(player.shape, player.radius, 1, player.color);
      ctx.restore();
      animationFrameId = requestAnimationFrame(render);
    };
    render(performance.now());
    return () => cancelAnimationFrame(animationFrameId);
  }, [graphics, theme]);

  return <canvas ref={canvasRef} className="block w-full h-full" style={{ touchAction: 'none' }} />;
};

export default GameCanvas;
